(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-975":{scenario:{company:"Tung Lam Ward Public Service Center",supervisor:{name:"Phan Thị Ngọc Lan",role:{vi:"Phó Giám đốc Trung tâm Phục vụ hành chính công",en:"Deputy Director, Public Service Center"}},ref_code:"CT-7720",title:{vi:"Đúng quy định. Đúng lệ phí. Không phong bì.",en:"By the rules. Right fee. No envelopes."},brief:{vi:"Đây là tình huống đào tạo. Một công dân đề nghị chứng thực bản sao từ bản chính (hồ sơ CT-7720): bằng tốt nghiệp 1 trang x 3 bản; hợp đồng thuê nhà 6 trang x 2 bản; Giấy chứng nhận quyền sử dụng đất (GCN) 4 trang x 2 bản, bản chính có vết tẩy xóa, sửa chữa nội dung ở trang 3 mà không có xác nhận của cơ quan cấp. Sửa mã xử lý GCN và lệ phí chứng thực trên bản nháp theo biểu lệ phí mô phỏng, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. A citizen asks for certified copies from originals (file CT-7720): a diploma, 1 page x 3 copies; a house lease, 6 pages x 2 copies; a land use right certificate (land title), 4 pages x 2 copies, whose original shows erasures and alterations on page 3 without confirmation by the issuing authority. Correct the land title handling code and the certification fee in the draft using the simulated fee schedule, then write an evidence-based report."},reference_title:{vi:"Quy trình chứng thực & biểu lệ phí đã duyệt · CT-7720",en:"Approved certification procedure & fee schedule · CT-7720"},fields:[{id:"GCN_ACTION",label:{vi:"Mã xử lý GCN (XL-01 nhận/02 bổ sung/03 từ chối)",en:"Land title code (XL-01 accept/02 supplement/03 refuse)"},initial:"XL-01",expected:"XL-03",choices:["XL-01","XL-02","XL-03"],reference:"Quy trình chứng thực bản sao",hint:{vi:"Bản chính bị tẩy xóa, sửa chữa nội dung không hợp lệ không được dùng làm cơ sở chứng thực; nộp thêm giấy tờ khác cũng không khắc phục được.",en:"An original with invalid erasures or alterations cannot be the basis for certification; extra documents do not cure it."}},{id:"FEE_VND",label:{vi:"Lệ phí chứng thực (đồng)",en:"Certification fee (VND)"},initial:"46000",expected:"22000",reference:"Biểu lệ phí chứng thực",ref_value:{vi:"2000 đ/trang cho 2 trang đầu; từ trang 3: 1000 đ/trang; tính theo từng bản",en:"2000 VND/page for the first 2 pages; 1000 VND/page from page 3; per copy"},hint:{vi:"Chỉ thu lệ phí cho giấy tờ được chứng thực và áp dụng bậc giá theo trang cho từng bản.",en:"Charge only for documents actually certified and apply the page tiers to each copy."}}],sop32:{vi:"Lệ phí mỗi bản = 2000 đ x số trang trong 2 trang đầu + 1000 đ x số trang từ trang 3, tối đa 200000 đ/bản; tổng = cộng các bản được chứng thực, không thu với giấy tờ bị từ chối (số liệu mô phỏng).",en:"Fee per copy = 2000 VND x pages within the first 2 + 1000 VND x pages from page 3, capped at 200000 VND per copy; total = sum of certified copies, no fee for refused documents (simulated)."},context:{label:"ONE-STOP / CT-7720",metrics:[{label:{vi:"Bằng tốt nghiệp (trang x bản)",en:"Diploma (pages x copies)"},value:"1 x 3"},{label:{vi:"Hợp đồng thuê nhà (trang x bản)",en:"Lease (pages x copies)"},value:"6 x 2"},{label:{vi:"GCN (trang x bản)",en:"Land title (pages x copies)"},value:"4 x 2"}]},crisis:{vi:"Người nộp hồ sơ đặt một phong bì lên quầy: “Chị chứng thực luôn cái GCN giúp em, chỗ sửa là do cán bộ cũ ghi nhầm thôi. Chiều nay em phải nộp ngân hàng để giải ngân, chị thông cảm.”",en:"The applicant puts an envelope on the counter: “Please certify the land title too, the correction was just an old officer's mistake. I must give it to the bank this afternoon for the loan, please understand.”"},options:{safe:{vi:"Từ chối phong bì và từ chối chứng thực GCN, giải thích căn cứ bằng văn bản, hướng dẫn đề nghị cơ quan đã cấp đính chính; chứng thực giấy tờ hợp lệ và báo lãnh đạo trung tâm.",en:"Refuse the envelope and the land title certification, explain the legal basis in writing and guide the citizen to the issuing authority for correction; certify the valid papers and inform the director."},shortcut:{vi:"Chứng thực luôn GCN vì người dân cần gấp, ghi chú vết sửa vào sổ chứng thực.",en:"Certify the land title anyway because it is urgent and note the alteration in the register."},wait:{vi:"Giữ hồ sơ lại không trả lời, chờ lãnh đạo đi công tác về quyết định.",en:"Keep the file without answering and wait for the director to return from a trip."}},questions:{vi:["Vì sao GCN phải xử lý mã XL-03? Lệ phí 22000 đ được tính từ những bản nào?","Bạn giải thích với người dân thế nào để vừa đúng quy định vừa giữ thái độ phục vụ, và xử lý việc đưa phong bì ra sao?"],en:["Why must the land title take code XL-03? Which copies make up the corrected fee?","How do you explain the decision to the citizen while staying service-minded, and how do you handle the envelope?"]},hints:{vi:["Kiểm tra tình trạng từng bản chính trước khi tiếp nhận vào sổ chứng thực.","Tính lệ phí riêng cho từng bản theo bậc trang ở SOP mục 3.2, bỏ phần giấy tờ bị từ chối.","Đọc lại SOP mục 4.2: không nhận lợi ích, không làm sai quy trình; giải thích bằng văn bản và báo lãnh đạo."],en:["Check the condition of each original before entering it in the certification register.","Compute the fee per copy using the page tiers in SOP 3.2 and leave out refused documents.","Re-read SOP 4.2: accept no benefits and never bend the procedure; explain in writing and inform the director."]}},learning:{summary:{vi:"Chuyên viên bộ phận Một cửa tiếp nhận, kiểm tra, hướng dẫn và trả kết quả thủ tục hành chính cho người dân, doanh nghiệp: chứng thực, hộ tịch, đăng ký kinh doanh hộ cá thể, đất đai và nhiều lĩnh vực khác. Nghề là gương mặt của chính quyền, đòi hỏi nắm chắc quy định, kỹ năng giao tiếp, số hóa hồ sơ và liêm chính tuyệt đối.",en:"A one-stop officer receives, checks, guides and returns administrative procedures for citizens and businesses: certification, civil status, household business registration, land and more. The role is the face of local government and requires solid knowledge of regulations, communication skills, file digitization and absolute integrity."},responsibilities:{vi:["Hướng dẫn người dân thành phần hồ sơ, trình tự và lệ phí theo thủ tục đã công bố.","Kiểm tra tính đầy đủ, hợp lệ của hồ sơ; hướng dẫn bổ sung một lần bằng văn bản.","Tiếp nhận, cấp giấy hẹn, số hóa hồ sơ và chuyển cơ quan có thẩm quyền giải quyết.","Thu lệ phí đúng biểu, trả kết quả và theo dõi hồ sơ trễ hạn trên hệ thống.","Tiếp nhận phản ánh, kiến nghị và báo cáo lãnh đạo các vướng mắc, hành vi tiêu cực."],en:["Guide citizens on required documents, steps and fees for each published procedure.","Check completeness and validity; request any missing items once, in writing.","Receive files, issue appointment slips, digitize records and forward them to the competent office.","Collect fees per schedule, return results and track overdue files in the system.","Handle feedback and complaints and report obstacles or misconduct to management."]},competencies:[{name:{vi:"Nắm vững thủ tục",en:"Procedure mastery"},desc:{vi:"Hiểu thành phần hồ sơ, thời hạn, thẩm quyền và các trường hợp từ chối của từng thủ tục.",en:"Know the documents, deadlines, authority and refusal grounds for each procedure."}},{name:{vi:"Giao tiếp phục vụ",en:"Service communication"},desc:{vi:"Lắng nghe, giải thích dễ hiểu, kiên nhẫn với người cao tuổi và người yếu thế.",en:"Listen, explain plainly and stay patient with elderly and vulnerable people."}},{name:{vi:"Số hóa & hệ thống",en:"Digitization & systems"},desc:{vi:"Quét, ký số, cập nhật hồ sơ đúng hạn trên hệ thống giải quyết thủ tục hành chính.",en:"Scan, sign digitally and update files on time in the procedure management system."}},{name:{vi:"Chính xác & cẩn trọng",en:"Accuracy & care"},desc:{vi:"Phát hiện giấy tờ bị sửa chữa, không hợp lệ và tính đúng lệ phí.",en:"Spot altered or invalid documents and calculate fees correctly."}},{name:{vi:"Liêm chính công vụ",en:"Public integrity"},desc:{vi:"Từ chối mọi lợi ích, không gây phiền hà, không yêu cầu giấy tờ ngoài quy định.",en:"Refuse all benefits, never harass and never ask for documents beyond the rules."}}],knowledge:{vi:["Nghị định 23/2015/NĐ-CP về cấp bản sao từ sổ gốc, chứng thực bản sao từ bản chính, chứng thực chữ ký và văn bản sửa đổi.","Nghị định 61/2018/NĐ-CP về cơ chế một cửa, một cửa liên thông và các văn bản sửa đổi, thay thế.","Nghị định 45/2020/NĐ-CP về thực hiện thủ tục hành chính trên môi trường điện tử.","Luật Giao dịch điện tử số 20/2023/QH15 và Luật Bảo vệ dữ liệu cá nhân năm 2025 cùng văn bản hướng dẫn.","Luật Phòng, chống tham nhũng số 36/2018/QH14 và quy tắc ứng xử của cán bộ, công chức."],en:["Decree 23/2015/ND-CP on copies from master registers, certified copies from originals, signature certification and its amendments.","Decree 61/2018/ND-CP on the one-stop and inter-agency one-stop mechanism and its amendments and replacements.","Decree 45/2020/ND-CP on administrative procedures in the electronic environment.","Law on Electronic Transactions No. 20/2023/QH15 and the 2025 Personal Data Protection Law with its guidance.","Anti-Corruption Law No. 36/2018/QH14 and the code of conduct for civil servants."]},tools:["Hệ thống thông tin giải quyết thủ tục hành chính","Cổng Dịch vụ công quốc gia","Máy quét và chữ ký số","Hệ thống xếp hàng tự động","Sổ chứng thực điện tử","Thiết bị đánh giá mức độ hài lòng"],kpis:{vi:["Tỷ lệ hồ sơ giải quyết đúng hạn.","Tỷ lệ hồ sơ phải yêu cầu bổ sung quá một lần (mục tiêu bằng 0).","Chỉ số hài lòng của người dân sau giao dịch.","Tỷ lệ hồ sơ được số hóa và tái sử dụng dữ liệu."],en:["Share of files resolved on time.","Files needing more than one supplement request (target zero).","Citizen satisfaction score after each visit.","Share of files digitized with data reused."]},day:[{time:"07:30",vi:"Mở quầy, kiểm tra hệ thống xếp hàng, máy quét và danh sách hồ sơ đến hạn trả.",en:"Open the counter, check the queue system, scanners and results due today."},{time:"08:00",vi:"Tiếp nhận, kiểm tra và hướng dẫn hồ sơ của người dân theo thứ tự số.",en:"Receive, check and guide citizens' files in queue order."},{time:"11:00",vi:"Số hóa, ký số hồ sơ đã nhận và chuyển phòng chuyên môn giải quyết.",en:"Digitize and sign received files and forward them to the specialist office."},{time:"14:00",vi:"Trả kết quả, thu lệ phí và gửi phiếu xin lỗi, hẹn lại với hồ sơ trễ hạn.",en:"Return results, collect fees and issue apology and new-date slips for late files."},{time:"16:30",vi:"Tổng hợp phản ánh, báo cáo số liệu trong ngày cho lãnh đạo trung tâm.",en:"Compile feedback and report daily figures to the center's leadership."}],mistakes:{vi:["Tiếp nhận bản chính bị tẩy xóa, sửa chữa để chứng thực vì người dân cần gấp.","Tính lệ phí cùng một mức cho mọi trang hoặc thu cả giấy tờ bị từ chối.","Yêu cầu bổ sung nhiều lần hoặc đòi giấy tờ ngoài thành phần hồ sơ đã công bố."],en:["Accepting altered originals for certification because the citizen is in a hurry.","Charging one rate for every page or charging for refused documents.","Requesting supplements several times or asking for documents outside the published list."]},career:[{vi:"Nhân viên tiếp nhận hồ sơ một cửa",en:"One-stop reception officer"},{vi:"Chuyên viên bộ phận Một cửa",en:"Public service one-stop officer"},{vi:"Tổ trưởng bộ phận tiếp nhận và trả kết quả",en:"Reception and results team lead"},{vi:"Lãnh đạo Trung tâm Phục vụ hành chính công",en:"Director of a public service center"}],glossary:[{term:"Một cửa",vi:"Cơ chế tiếp nhận hồ sơ và trả kết quả tập trung tại một đầu mối cho người dân, doanh nghiệp.",en:"A mechanism where citizens and businesses file and collect results at a single point."},{term:"Chứng thực bản sao",vi:"Việc cơ quan có thẩm quyền xác nhận bản sao đúng với bản chính.",en:"Official confirmation by a competent body that a copy matches the original."},{term:"Phiếu hẹn",vi:"Giấy tiếp nhận hồ sơ và hẹn trả kết quả, ghi rõ ngày trả theo thời hạn giải quyết.",en:"A receipt confirming the filing and the result date under the processing deadline."},{term:"DVC trực tuyến",vi:"Dịch vụ công trực tuyến cho phép nộp hồ sơ, thanh toán và nhận kết quả qua mạng.",en:"Online public services for filing, payment and receiving results over the internet."},{term:"Số hóa hồ sơ",vi:"Chuyển giấy tờ thành dữ liệu điện tử có giá trị pháp lý để lưu và tái sử dụng.",en:"Converting paper documents into legally valid electronic data for storage and reuse."}],quiz:[{q:{vi:"Một giấy tờ 5 trang cần 2 bản sao chứng thực. Theo biểu mô phỏng (2000 đ/trang cho 2 trang đầu, 1000 đ/trang từ trang 3), lệ phí là bao nhiêu?",en:"A 5-page document needs 2 certified copies. Using the simulated schedule (2000 VND/page for the first 2 pages, 1000 VND/page from page 3), what is the fee?"},options:{vi:["20000 đ","14000 đ","10000 đ","7000 đ"],en:["20000 VND","14000 VND","10000 VND","7000 VND"]},answer:1,explain:{vi:"Mỗi bản: 2 x 2000 + 3 x 1000 = 7000 đ; hai bản là 14000 đ.",en:"Per copy: 2 x 2000 + 3 x 1000 = 7000 VND; two copies cost 14000 VND."}},{q:{vi:"Bản chính có vết tẩy xóa, sửa chữa nội dung không hợp lệ. Bộ phận chứng thực xử lý thế nào?",en:"An original shows invalid erasures and alterations. What does the certification desk do?"},options:{vi:["Chứng thực và ghi chú","Yêu cầu nộp thêm bản photo","Chứng thực nếu người dân cam kết","Từ chối chứng thực và giải thích lý do"],en:["Certify and add a note","Ask for an extra photocopy","Certify if the citizen signs a pledge","Refuse certification and explain why"]},answer:3,explain:{vi:"Bản chính bị tẩy xóa, sửa chữa không hợp lệ không được dùng làm cơ sở chứng thực bản sao.",en:"An original with invalid erasures or alterations cannot be used to certify copies."}},{q:{vi:"Người dân đặt phong bì lên quầy để được giải quyết nhanh. Bạn làm gì?",en:"A citizen leaves an envelope on the counter to speed things up. What do you do?"},options:{vi:["Từ chối, giải thích quy định và báo lãnh đạo theo quy trình","Nhận rồi trả lại sau","Nhận nếu số tiền nhỏ","Làm như không thấy"],en:["Refuse, explain the rules and report it per procedure","Take it and return it later","Take it if the amount is small","Pretend not to see it"]},answer:0,explain:{vi:"Nhận lợi ích để giải quyết công việc là hành vi tham nhũng; phải từ chối và báo cáo.",en:"Accepting benefits for official work is corruption; refuse and report it."}},{q:{vi:"Hồ sơ thiếu thành phần, cán bộ một cửa phải hướng dẫn bổ sung như thế nào?",en:"When a file is incomplete, how must the officer request the missing items?"},options:{vi:["Bằng lời, nhiều lần khi phát hiện","Qua điện thoại cá nhân","Một lần, đầy đủ, bằng văn bản","Không cần hướng dẫn"],en:["Verbally, each time something is found","By personal phone","Once, completely, in writing","No guidance is needed"]},answer:2,explain:{vi:"Quy định yêu cầu hướng dẫn đầy đủ một lần bằng văn bản để tránh gây phiền hà cho người dân.",en:"The rules require a single, complete written request to avoid burdening citizens."}}]}},"KK-976":{scenario:{company:"Lam Giang Provincial Digital Center",supervisor:{name:"Khúc Duy Phong",role:{vi:"Trưởng phòng Chính phủ số",en:"Head of Digital Government"}},ref_code:"DVC-0315",title:{vi:"Đánh giá thật. Lợi ích thật. Dữ liệu an toàn.",en:"Honest rating. Real benefit. Safe data."},brief:{vi:"Đây là tình huống đào tạo. Bạn lập đề án nâng cấp dịch vụ công DVC-0315 (cấp phép tổ chức sự kiện, mô phỏng). Quy định chuyên ngành buộc người nộp đến trực tiếp ký nhận kết quả và xuất trình bản gốc tại quầy. Dữ liệu: 48000 hồ sơ/năm, tỷ lệ nộp trực tuyến mục tiêu 65%; chi phí xã hội mỗi hồ sơ: trực tiếp 185000 đ, trực tuyến toàn trình 60000 đ, trực tuyến một phần 95000 đ. Sửa mức độ dịch vụ và lợi ích hằng năm (triệu đồng) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"This is a training scenario. You are drafting the upgrade proposal for public service DVC-0315 (event permit, simulated). Sector rules require applicants to come in person to sign for the result and show originals at the counter. Data: 48000 files/year, target online share 65%; social cost per file: in person 185000 VND, full online 60000 VND, partial online 95000 VND. Correct the service level and the annual benefit (million VND) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Phiếu đánh giá mức độ DVC & phân tích lợi ích · DVC-0315",en:"Service level assessment & benefit analysis · DVC-0315"},fields:[{id:"DVC_LEVEL",label:{vi:"Mức độ dịch vụ công trực tuyến",en:"Online public service level"},initial:"FULL-ONLINE",expected:"PARTIAL-ONLINE",choices:["FULL-ONLINE","PARTIAL-ONLINE","IN-PERSON"],reference:"Phiếu đánh giá mức độ DVC",hint:{vi:"Chỉ cần một bước bắt buộc người dân đến trực tiếp là dịch vụ chưa đạt mức toàn trình.",en:"A single mandatory in-person step means the service is not yet fully online."}},{id:"BENEFIT_M",label:{vi:"Lợi ích xã hội hằng năm (triệu đồng)",en:"Annual social benefit (million VND)"},initial:"6000",expected:"2808",reference:"Bảng phân tích chi phí - lợi ích",ref_value:{vi:"48000 hồ sơ/năm; trực tuyến 65%; chi phí: trực tiếp 185000, toàn trình 60000, một phần 95000 đ",en:"48000 files/yr; 65% online; cost: in person 185000, full 60000, partial 95000 VND"},hint:{vi:"Lợi ích chỉ phát sinh trên phần hồ sơ chuyển sang trực tuyến và theo chi phí của đúng mức độ dịch vụ.",en:"Benefits arise only on files that move online and at the cost of the correct service level."}}],sop32:{vi:"Lợi ích hằng năm = số hồ sơ/năm x tỷ lệ nộp trực tuyến x (chi phí hồ sơ trực tiếp - chi phí hồ sơ trực tuyến của đúng mức độ dịch vụ); quy đổi ra triệu đồng.",en:"Annual benefit = files per year x online share x (in-person cost per file - online cost per file at the correct service level); convert to million VND."},context:{label:"EA / DVC-0315",metrics:[{label:{vi:"Hồ sơ mỗi năm",en:"Files per year"},value:"48,000"},{label:{vi:"Tỷ lệ trực tuyến mục tiêu",en:"Target online share"},value:"65%"},{label:{vi:"Chi phí trực tiếp / hồ sơ",en:"In-person cost / file"},value:"185,000 VND"},{label:{vi:"Chi phí một phần / hồ sơ",en:"Partial online cost / file"},value:"95,000 VND"}]},crisis:{vi:"Nhà thầu đề nghị xuất 50000 bản ghi công dân thật từ cơ sở dữ liệu của tỉnh để “huấn luyện chatbot” kịp buổi trình diễn với lãnh đạo tỉnh tuần sau; trưởng phòng đã đồng ý miệng và dặn đừng làm thủ tục cho mất thời gian.",en:"The vendor asks to export 50000 real citizen records from the provincial database to “train the chatbot” for next week's demo to provincial leaders; your manager agreed verbally and said to skip the paperwork."},options:{safe:{vi:"Không xuất dữ liệu thật khi chưa có căn cứ pháp lý, hợp đồng xử lý dữ liệu và đánh giá tác động; báo lãnh đạo sở bằng văn bản, dùng dữ liệu tổng hợp hoặc đã ẩn danh cho buổi trình diễn.",en:"Do not export real data without a legal basis, a processing agreement and an impact assessment; inform department leadership in writing and use synthetic or anonymized data for the demo."},shortcut:{vi:"Xuất 50000 bản ghi cho nhà thầu vì trưởng phòng đã đồng ý, xóa sau buổi trình diễn.",en:"Export the 50000 records since the manager agreed and delete them after the demo."},wait:{vi:"Không trả lời nhà thầu, để trưởng phòng tự quyết định.",en:"Do not answer the vendor and let the manager decide."}},questions:{vi:["Vì sao DVC-0315 chỉ đạt PARTIAL-ONLINE? Lợi ích 2808 triệu đồng được tính từ những dữ liệu nào?","Bạn xử lý đề nghị xuất dữ liệu công dân thật thế nào để vẫn giữ tiến độ trình diễn mà tuân thủ pháp luật?"],en:["Why does DVC-0315 only reach PARTIAL-ONLINE? Which data produces the corrected annual benefit?","How do you handle the request for real citizen data while keeping the demo on schedule and staying lawful?"]},hints:{vi:["Rà soát từng bước của quy trình: bước nào người dân vẫn phải có mặt tại quầy?","Áp dụng tỷ lệ trực tuyến và chênh lệch chi phí của đúng mức độ dịch vụ ở SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu cá nhân chỉ được xử lý khi có căn cứ; chỉ đạo miệng không thay thế thủ tục."],en:["Walk through each step: at which step must the citizen still appear at the counter?","Apply the online share and the cost gap of the correct service level in SOP 3.2.","Re-read SOP 4.2: personal data needs a lawful basis; a verbal instruction never replaces due process."]}},learning:{summary:{vi:"Chuyên viên chính phủ số thiết kế, triển khai và đo lường dịch vụ công trực tuyến, kết nối chia sẻ dữ liệu giữa các cơ quan và thúc đẩy chuyển đổi số khu vực công. Nghề kết hợp tư duy chiến lược, thiết kế dịch vụ lấy người dùng làm trung tâm, kiến trúc dữ liệu, an toàn thông tin và bảo vệ dữ liệu cá nhân.",en:"A GovTech and digital government specialist designs, deploys and measures online public services, connects data sharing across agencies and drives public sector digital transformation. The role combines strategic thinking, user-centered service design, data architecture, information security and personal data protection."},responsibilities:{vi:["Rà soát, đơn giản hóa và tái thiết kế quy trình thủ tục hành chính trước khi số hóa.","Đánh giá mức độ dịch vụ công trực tuyến, đề xuất lộ trình nâng lên toàn trình.","Lập đề án, phân tích chi phí - lợi ích và chỉ số đo lường cho dự án chuyển đổi số.","Điều phối kết nối dữ liệu giữa các hệ thống, bảo đảm an toàn thông tin theo cấp độ.","Giám sát nhà thầu, kiểm soát việc xử lý dữ liệu cá nhân và báo cáo kết quả triển khai."],en:["Review, simplify and redesign administrative procedures before digitizing them.","Assess online service levels and propose a roadmap to full online delivery.","Write proposals, cost-benefit analyses and metrics for digital transformation projects.","Coordinate data integration between systems with security by information system level.","Supervise vendors, control personal data processing and report deployment results."]},competencies:[{name:{vi:"Tư duy chiến lược số",en:"Digital strategy"},desc:{vi:"Xác định ưu tiên, lộ trình và chỉ số thành công gắn với nhu cầu người dân.",en:"Set priorities, roadmaps and success metrics tied to citizens' needs."}},{name:{vi:"Thiết kế dịch vụ",en:"Service design"},desc:{vi:"Vẽ hành trình người dùng, loại bỏ bước thừa và thử nghiệm nguyên mẫu.",en:"Map user journeys, remove needless steps and test prototypes."}},{name:{vi:"Kiến trúc & dữ liệu",en:"Architecture & data"},desc:{vi:"Hiểu khung kiến trúc, nền tảng tích hợp, chia sẻ dữ liệu và nguyên tắc chỉ khai báo một lần.",en:"Understand architecture frameworks, integration platforms, data sharing and the once-only principle."}},{name:{vi:"Phân tích kinh tế",en:"Economic analysis"},desc:{vi:"Tính chi phí tuân thủ, lợi ích xã hội và thời gian hoàn vốn của dự án số.",en:"Estimate compliance cost, social benefit and payback of digital projects."}},{name:{vi:"Bảo vệ dữ liệu",en:"Data protection"},desc:{vi:"Áp dụng căn cứ xử lý, ẩn danh, đánh giá tác động và kiểm soát nhà thầu.",en:"Apply lawful bases, anonymization, impact assessments and vendor controls."}}],knowledge:{vi:["Nghị định 42/2022/NĐ-CP về cung cấp thông tin và dịch vụ công trực tuyến: dịch vụ toàn trình và một phần.","Nghị định 45/2020/NĐ-CP về thực hiện thủ tục hành chính trên môi trường điện tử.","Nghị định 47/2020/NĐ-CP về quản lý, kết nối và chia sẻ dữ liệu số của cơ quan nhà nước; Luật Dữ liệu năm 2024.","Nghị định 85/2016/NĐ-CP và TCVN 11930:2017 về bảo đảm an toàn hệ thống thông tin theo cấp độ.","Luật Bảo vệ dữ liệu cá nhân năm 2025 và văn bản hướng dẫn: căn cứ xử lý, đánh giá tác động, bên xử lý dữ liệu."],en:["Decree 42/2022/ND-CP on online information and public services: full online and partial online services.","Decree 45/2020/ND-CP on administrative procedures in the electronic environment.","Decree 47/2020/ND-CP on managing, connecting and sharing digital data of state agencies; the 2024 Data Law.","Decree 85/2016/ND-CP and TCVN 11930:2017 on information system security by level.","The 2025 Personal Data Protection Law and its guidance: lawful bases, impact assessments, data processors."]},tools:["Cổng dịch vụ công và hệ thống một cửa điện tử","Nền tảng tích hợp, chia sẻ dữ liệu (LGSP)","Công cụ thiết kế trải nghiệm và nguyên mẫu","Bảng điều khiển phân tích (BI)","Công cụ quản lý dự án Agile","Công cụ ẩn danh và sinh dữ liệu tổng hợp"],kpis:{vi:["Tỷ lệ hồ sơ nộp trực tuyến trên tổng số hồ sơ.","Tỷ lệ dịch vụ công đạt mức toàn trình.","Mức độ hài lòng của người dùng (CSAT) với dịch vụ số.","Số loại giấy tờ được thay bằng dữ liệu chia sẻ, không yêu cầu nộp lại."],en:["Online filings as a share of all files.","Share of public services delivered fully online.","User satisfaction (CSAT) with digital services.","Document types replaced by shared data and no longer requested."]},day:[{time:"08:00",vi:"Xem bảng điều khiển: hồ sơ trực tuyến, lỗi kết nối, phản ánh của người dùng.",en:"Check the dashboard: online filings, integration errors and user feedback."},{time:"09:30",vi:"Làm việc với sở chuyên ngành tái thiết kế quy trình một thủ tục.",en:"Work with a line department to redesign one procedure."},{time:"13:30",vi:"Phân tích chi phí - lợi ích và cập nhật đề án nâng cấp dịch vụ.",en:"Run the cost-benefit analysis and update the service upgrade proposal."},{time:"15:00",vi:"Họp nhà thầu, rà soát kế hoạch kiểm thử và phương án dữ liệu thử nghiệm.",en:"Meet the vendor to review the test plan and test data approach."},{time:"17:00",vi:"Báo cáo tiến độ, rủi ro và kiến nghị cho lãnh đạo sở.",en:"Report progress, risks and recommendations to department leadership."}],mistakes:{vi:["Báo cáo dịch vụ là toàn trình dù vẫn còn bước bắt buộc đến trực tiếp.","Tính lợi ích trên toàn bộ hồ sơ thay vì phần thực sự chuyển sang trực tuyến.","Cho nhà thầu dùng dữ liệu công dân thật để kiểm thử mà không có căn cứ và kiểm soát."],en:["Reporting a service as fully online while an in-person step remains.","Computing benefits on all files instead of those that actually move online.","Letting vendors test with real citizen data without a legal basis and controls."]},career:[{vi:"Chuyên viên ứng dụng công nghệ thông tin",en:"IT applications officer"},{vi:"Chuyên viên chính phủ số",en:"Digital government specialist"},{vi:"Trưởng nhóm thiết kế dịch vụ và dữ liệu",en:"Service design and data lead"},{vi:"Giám đốc chuyển đổi số khu vực công",en:"Public sector chief digital officer"}],glossary:[{term:"DVC toàn trình",vi:"Dịch vụ công mà toàn bộ việc thực hiện và giải quyết thủ tục đều diễn ra trên môi trường mạng.",en:"A public service where the whole procedure is carried out and resolved online."},{term:"DVC một phần",vi:"Dịch vụ công trực tuyến chưa đáp ứng toàn trình, còn bước người dân phải thực hiện trực tiếp.",en:"An online service that is not fully online and still needs some in-person steps."},{term:"LGSP",vi:"Nền tảng tích hợp, chia sẻ dữ liệu cấp bộ, cấp tỉnh kết nối các hệ thống thông tin.",en:"Ministry or provincial data integration and sharing platform connecting information systems."},{term:"Once-only",vi:"Nguyên tắc người dân chỉ cung cấp một thông tin một lần, cơ quan nhà nước tự chia sẻ cho nhau.",en:"The principle that citizens provide information once and agencies share it among themselves."},{term:"Ẩn danh hóa",vi:"Xử lý dữ liệu để không còn xác định được cá nhân, kể cả khi kết hợp dữ liệu khác.",en:"Processing data so individuals can no longer be identified, even when combined with other data."}],quiz:[{q:{vi:"Dịch vụ cho nộp và thanh toán trực tuyến nhưng bắt buộc đến quầy ký nhận kết quả thuộc mức nào?",en:"A service allows online filing and payment but requires signing for the result at the counter. Which level is it?"},options:{vi:["Toàn trình","Không phải dịch vụ công","Một phần","Toàn trình có điều kiện"],en:["Full online","Not a public service","Partial online","Conditionally full online"]},answer:2,explain:{vi:"Còn bước bắt buộc thực hiện trực tiếp nên dịch vụ chỉ đạt mức một phần.",en:"A mandatory in-person step means the service is only partial online."}},{q:{vi:"10000 hồ sơ/năm, 50% chuyển trực tuyến, chi phí trực tiếp 150000 đ, trực tuyến 70000 đ. Lợi ích hằng năm?",en:"10000 files/year, 50% move online, in-person cost 150000 VND, online 70000 VND. What is the annual benefit?"},options:{vi:["400 triệu đồng","800 triệu đồng","750 triệu đồng","350 triệu đồng"],en:["400 million VND","800 million VND","750 million VND","350 million VND"]},answer:0,explain:{vi:"10000 x 0.5 x (150000 - 70000) = 400 triệu đồng.",en:"10000 x 0.5 x (150000 - 70000) = 400 million VND."}},{q:{vi:"Nguyên tắc “chỉ khai báo một lần” (once-only) nghĩa là gì?",en:"What does the once-only principle mean?"},options:{vi:["Mỗi người chỉ được nộp một hồ sơ","Cơ quan nhà nước tái sử dụng dữ liệu đã có thay vì yêu cầu nộp lại","Mỗi thủ tục chỉ có một bước","Chỉ được đăng nhập một lần mỗi ngày"],en:["Each person may file only once","Agencies reuse existing data instead of asking again","Each procedure has only one step","Users may log in once a day"]},answer:1,explain:{vi:"Dữ liệu người dân đã cung cấp được chia sẻ giữa các cơ quan, giảm giấy tờ phải nộp lại.",en:"Data citizens already provided is shared among agencies, cutting repeat paperwork."}},{q:{vi:"Nhà thầu xin dữ liệu công dân thật để huấn luyện chatbot cho kịp trình diễn. Bạn làm gì?",en:"A vendor wants real citizen data to train a chatbot for a demo. What do you do?"},options:{vi:["Cấp vì có chỉ đạo miệng","Cấp một nửa số bản ghi","Cấp rồi yêu cầu xóa sau","Từ chối, báo cáo bằng văn bản và dùng dữ liệu tổng hợp hoặc ẩn danh"],en:["Provide it because of a verbal order","Provide half the records","Provide it and ask for deletion later","Refuse, report in writing and use synthetic or anonymized data"]},answer:3,explain:{vi:"Xử lý dữ liệu cá nhân cần căn cứ pháp lý và kiểm soát; dữ liệu tổng hợp đáp ứng được mục tiêu trình diễn.",en:"Personal data processing needs a lawful basis and controls; synthetic data meets the demo goal."}}]}},"KK-977":{scenario:{company:"Ngan Tung Land Registration Office",supervisor:{name:"Trịnh Văn Hòa",role:{vi:"Giám đốc Chi nhánh Văn phòng Đăng ký Đất đai",en:"Branch Director, Land Registration Office"}},ref_code:"DK-6093",title:{vi:"Đúng loại đất. Đúng diện tích đo đạc.",en:"Right land use code. Surveyed area only."},brief:{vi:"Đây là tình huống đào tạo. Bạn thẩm tra hồ sơ đăng ký biến động DK-6093 của một thửa đất ở thuộc phường Ngân Tùng (đơn vị hành chính đô thị, mô phỏng). Tọa độ các đỉnh theo biên bản đo đạc (m, hệ VN-2000 rút gọn): A(0;0), B(24;0), C(26.5;18), D(1.5;16). Tờ khai của người sử dụng đất ghi 432 m2, gồm cả phần đang sử dụng lấn ra ngõ chung. Sửa mã loại đất và diện tích thửa trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"This is a training scenario. You are verifying change registration file DK-6093 for a residential parcel in Ngan Tung ward (an urban administrative unit, simulated). Vertex coordinates from the survey record (m, reduced VN-2000): A(0;0), B(24;0), C(26.5;18), D(1.5;16). The land user's declaration states 432 m2, including a strip used by encroaching on the shared alley. Correct the land use code and the parcel area in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Trích lục & biên bản đo đạc đã duyệt · DK-6093",en:"Approved cadastral extract & survey record · DK-6093"},fields:[{id:"LAND_CODE",label:{vi:"Mã loại đất",en:"Land use code"},initial:"ONT",expected:"ODT",choices:["ONT","ODT","CLN"],reference:"Trích lục bản đồ địa chính",hint:{vi:"Đất ở tại đô thị và đất ở tại nông thôn có ký hiệu khác nhau, xác định theo đơn vị hành chính nơi có thửa đất.",en:"Urban and rural residential land use different codes, set by the administrative unit where the parcel lies."}},{id:"AREA_M2",label:{vi:"Diện tích thửa (m2)",en:"Parcel area (m2)"},initial:"432",expected:"414.5",reference:"Biên bản đo đạc thửa đất",ref_value:{vi:"A(0;0), B(24;0), C(26.5;18), D(1.5;16) theo thứ tự trên đường bao",en:"A(0;0), B(24;0), C(26.5;18), D(1.5;16) in boundary order"},hint:{vi:"Tính diện tích đa giác từ tọa độ đỉnh bằng công thức Gauss, không lấy số theo tờ khai.",en:"Compute the polygon area from vertex coordinates with the shoelace formula, not from the declaration."}}],sop32:{vi:"Diện tích thửa = 1/2 x |tổng (x_i x y_(i+1) - x_(i+1) x y_i)| theo thứ tự đỉnh trên đường bao khép kín; diện tích ghi vào hồ sơ là diện tích đo đạc, không gồm phần lấn chiếm.",en:"Parcel area = 1/2 x |sum of (x_i x y_(i+1) - x_(i+1) x y_i)| over the closed boundary vertices in order; the recorded area is the surveyed area, excluding encroached land."},context:{label:"LIS / DK-6093",metrics:[{label:{vi:"Hệ tọa độ",en:"Coordinate system"},value:"VN-2000"},{label:{vi:"Số đỉnh thửa",en:"Parcel vertices"},value:"4"},{label:{vi:"Diện tích theo tờ khai",en:"Declared area"},value:"432 m2"}]},crisis:{vi:"Một người môi giới nhắn: “Em cứ giữ 432 m2 như tờ khai, phần ngõ chung ai đo lại đâu, chủ nhà sẽ hậu tạ. Ký sớm giúp anh để kịp công chứng hợp đồng chuyển nhượng tuần này.”",en:"A broker messages you: “Just keep 432 m2 as declared, nobody will re-measure the shared alley and the owner will thank you generously. Sign it soon so the sale contract can be notarized this week.”"},options:{safe:{vi:"Ghi mã loại đất và diện tích theo kết quả đo đạc, từ chối mọi lợi ích, lập biên bản phần lấn ngõ chung; báo giám đốc chi nhánh và chuyển cơ quan có thẩm quyền xem xét theo quy định.",en:"Record the land code and the surveyed area, refuse any benefit and document the alley encroachment; inform the branch director and refer it to the competent authority."},shortcut:{vi:"Giữ diện tích 432 m2 theo tờ khai cho kịp công chứng, điều chỉnh sau nếu có tranh chấp.",en:"Keep the declared 432 m2 so notarization can proceed and adjust later if a dispute arises."},wait:{vi:"Treo hồ sơ, không trả lời, chờ chủ đất tự giải quyết với hàng xóm.",en:"Leave the file pending without reply until the owner settles it with the neighbors."}},questions:{vi:["Vì sao thửa đất mang mã ODT? Trình bày cách tính diện tích từ tọa độ và phần chênh so với tờ khai.","Việc ghi nhận phần lấn ngõ chung vào diện tích thửa gây rủi ro pháp lý gì, và bạn xử lý lời đề nghị “hậu tạ” ra sao?"],en:["Why does the parcel take code ODT? Show how you computed the area from coordinates and the gap with the declaration.","What legal risks arise from recording the encroached alley in the parcel area, and how do you handle the offered reward?"]},hints:{vi:["Xác định đơn vị hành chính của thửa đất trước khi chọn ký hiệu loại đất ở.","Liệt kê tọa độ theo đúng thứ tự đường bao rồi áp dụng công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: hồ sơ địa chính phải phản ánh đúng thực địa; mọi lợi ích được đề nghị phải từ chối và báo cáo."],en:["Identify the parcel's administrative unit before choosing the residential land code.","List the coordinates in boundary order and apply the formula in SOP 3.2.","Re-read SOP 4.2: cadastral records must match the ground; refuse and report any offered benefit."]}},learning:{summary:{vi:"Chuyên viên quản lý đất đai và địa chính thẩm tra hồ sơ đăng ký đất đai, cấp Giấy chứng nhận, đăng ký biến động, cập nhật bản đồ và cơ sở dữ liệu địa chính. Nghề bảo vệ quyền hợp pháp của người sử dụng đất và lợi ích công, đòi hỏi nắm chắc pháp luật đất đai, kỹ thuật đo đạc, GIS và liêm chính công vụ.",en:"A land administration and cadastral officer verifies land registration files, issues certificates, records changes and updates cadastral maps and databases. The role protects land users' lawful rights and the public interest, and requires solid land law, surveying techniques, GIS and public integrity."},responsibilities:{vi:["Thẩm tra hồ sơ đăng ký lần đầu, đăng ký biến động và cấp đổi Giấy chứng nhận.","Đối chiếu ranh giới, diện tích, mục đích sử dụng với bản đồ địa chính và quy hoạch.","Kiểm tra kết quả đo đạc, tính diện tích và xử lý chênh lệch so với giấy tờ.","Cập nhật cơ sở dữ liệu địa chính, chỉnh lý bản đồ và lưu trữ hồ sơ.","Phối hợp xác minh nguồn gốc đất, xử lý lấn chiếm và trả lời phản ánh của người dân."],en:["Verify first-time registration, change registration and certificate reissue files.","Check boundaries, area and land use against the cadastral map and land use plans.","Review survey results, compute areas and resolve gaps with the papers.","Update the cadastral database, revise maps and archive records.","Verify land origin, handle encroachment and answer citizens' feedback."]},competencies:[{name:{vi:"Pháp luật đất đai",en:"Land law"},desc:{vi:"Áp dụng đúng điều kiện cấp Giấy chứng nhận, đăng ký biến động và phân loại đất.",en:"Apply certificate conditions, change registration and land classification correctly."}},{name:{vi:"Đo đạc & bản đồ",en:"Surveying & mapping"},desc:{vi:"Đọc biên bản đo, tọa độ VN-2000, tính diện tích và kiểm tra sai số.",en:"Read survey records and VN-2000 coordinates, compute areas and check tolerances."}},{name:{vi:"GIS & cơ sở dữ liệu",en:"GIS & databases"},desc:{vi:"Chỉnh lý bản đồ số, đồng bộ dữ liệu không gian và thuộc tính.",en:"Edit digital maps and keep spatial and attribute data in sync."}},{name:{vi:"Thẩm tra hồ sơ",en:"File verification"},desc:{vi:"Phát hiện mâu thuẫn giữa tờ khai, giấy tờ nguồn gốc và kết quả đo đạc.",en:"Spot conflicts between declarations, origin documents and survey results."}},{name:{vi:"Liêm chính công vụ",en:"Public integrity"},desc:{vi:"Từ chối lợi ích, ghi nhận trung thực thực địa và báo cáo hành vi tiêu cực.",en:"Refuse benefits, record the ground truthfully and report misconduct."}}],knowledge:{vi:["Luật Đất đai số 31/2024/QH15: phân loại đất, đăng ký đất đai, cấp Giấy chứng nhận và quyền của người sử dụng đất.","Nghị định 101/2024/NĐ-CP về điều tra cơ bản đất đai, đăng ký, cấp Giấy chứng nhận và hệ thống thông tin đất đai.","Luật Đo đạc và bản đồ số 27/2018/QH14, hệ tọa độ quốc gia VN-2000 và quy định kỹ thuật bản đồ địa chính.","Ký hiệu loại đất trên bản đồ địa chính như ODT, ONT, LUC, CLN, TMD và cách xác định.","Luật Phòng, chống tham nhũng số 36/2018/QH14 và quy tắc ứng xử của công chức."],en:["Land Law No. 31/2024/QH15: land classification, registration, certificates and land users' rights.","Decree 101/2024/ND-CP on land surveys, registration, certificate issuance and the land information system.","Law on Surveying and Mapping No. 27/2018/QH14, the national VN-2000 datum and cadastral mapping rules.","Cadastral land use codes such as ODT, ONT, LUC, CLN and TMD and how they are assigned.","Anti-Corruption Law No. 36/2018/QH14 and the civil servant code of conduct."]},tools:["Hệ thống thông tin đất đai (LIS)","Phần mềm biên tập bản đồ địa chính","Máy toàn đạc điện tử và GNSS RTK","GIS (QGIS)","Chữ ký số và lưu trữ điện tử"],kpis:{vi:["Tỷ lệ hồ sơ đăng ký giải quyết đúng hạn.","Tỷ lệ hồ sơ phải trả lại do sai sót thẩm tra.","Mức đồng bộ giữa hồ sơ giấy, bản đồ và cơ sở dữ liệu địa chính.","Số khiếu nại do sai diện tích hoặc mục đích sử dụng."],en:["Share of registration files resolved on time.","Files returned because of verification errors.","Consistency between paper files, maps and the cadastral database.","Complaints caused by wrong area or land use."]},day:[{time:"08:00",vi:"Nhận hồ sơ chuyển từ bộ phận một cửa, phân loại theo loại thủ tục và thời hạn.",en:"Receive files from the one-stop desk and sort them by procedure and deadline."},{time:"09:30",vi:"Thẩm tra giấy tờ nguồn gốc, đối chiếu bản đồ địa chính và quy hoạch.",en:"Verify origin documents against the cadastral map and land use plan."},{time:"13:30",vi:"Kiểm tra biên bản đo đạc, tính diện tích từ tọa độ và lập phiếu chênh lệch.",en:"Check survey records, compute areas from coordinates and log discrepancies."},{time:"15:30",vi:"Chỉnh lý bản đồ số và cập nhật cơ sở dữ liệu địa chính.",en:"Revise the digital map and update the cadastral database."},{time:"17:00",vi:"Trình ký kết quả, báo cáo hồ sơ vướng mắc cho giám đốc chi nhánh.",en:"Submit results for signature and report problem files to the branch director."}],mistakes:{vi:["Ghi diện tích theo tờ khai thay vì theo kết quả đo đạc thực tế.","Nhầm ký hiệu đất ở đô thị và nông thôn khi thửa đất thuộc phường.","Bỏ qua phần lấn chiếm đất công, hợp thức hóa sai vào Giấy chứng nhận."],en:["Recording the declared area instead of the surveyed one.","Confusing urban and rural residential codes for a parcel in a ward.","Ignoring encroachment on public land and wrongly legalizing it on the certificate."]},career:[{vi:"Cán bộ địa chính cấp xã, phường",en:"Commune or ward cadastral officer"},{vi:"Chuyên viên đăng ký đất đai và địa chính",en:"Land registration and cadastral officer"},{vi:"Trưởng nhóm thẩm tra hồ sơ đất đai",en:"Land file verification lead"},{vi:"Giám đốc Văn phòng Đăng ký Đất đai",en:"Director of a land registration office"}],glossary:[{term:"Thửa đất",vi:"Phần diện tích đất được giới hạn bởi ranh giới xác định trên thực địa hoặc trên hồ sơ.",en:"A land area bounded by limits defined on the ground or in records."},{term:"ODT",vi:"Ký hiệu đất ở tại đô thị trên bản đồ và hồ sơ địa chính.",en:"Cadastral code for urban residential land."},{term:"VN-2000",vi:"Hệ quy chiếu và hệ tọa độ quốc gia Việt Nam dùng cho đo đạc và bản đồ.",en:"Vietnam's national reference and coordinate system for surveying and mapping."},{term:"Đăng ký biến động",vi:"Đăng ký thay đổi về người sử dụng, diện tích, mục đích hoặc quyền đối với thửa đất.",en:"Registering changes to the user, area, use or rights of a parcel."},{term:"Shoelace formula",vi:"Công thức Gauss tính diện tích đa giác từ tọa độ các đỉnh theo thứ tự.",en:"Gauss's formula for polygon area from ordered vertex coordinates."}],quiz:[{q:{vi:"Thửa đất có đỉnh A(0;0), B(10;0), C(8;6), D(0;6) theo thứ tự. Diện tích là bao nhiêu?",en:"A parcel has vertices A(0;0), B(10;0), C(8;6), D(0;6) in order. What is its area?"},options:{vi:["60 m2","48 m2","54 m2","108 m2"],en:["60 m2","48 m2","54 m2","108 m2"]},answer:2,explain:{vi:"Tổng tích chéo = 0 + 60 + 48 + 0 = 108; diện tích = 108 / 2 = 54 m2.",en:"Cross-product sum = 0 + 60 + 48 + 0 = 108; area = 108 / 2 = 54 m2."}},{q:{vi:"Thửa đất ở nằm trong một phường. Ký hiệu loại đất đúng là gì?",en:"A residential parcel lies in an urban ward. What is the correct land use code?"},options:{vi:["ODT","ONT","CLN","LUC"],en:["ODT","ONT","CLN","LUC"]},answer:0,explain:{vi:"ODT là đất ở tại đô thị; ONT là đất ở tại nông thôn.",en:"ODT is urban residential land; ONT is rural residential land."}},{q:{vi:"Hệ VN-2000 được dùng để làm gì trong địa chính?",en:"What is VN-2000 used for in cadastral work?"},options:{vi:["Mã hóa loại đất","Hệ quy chiếu, tọa độ quốc gia cho đo đạc và bản đồ","Phần mềm quản lý hồ sơ","Tiêu chuẩn lưu trữ giấy"],en:["Coding land use types","The national reference and coordinate system for surveys and maps","A file management software","A paper archiving standard"]},answer:1,explain:{vi:"VN-2000 là hệ quy chiếu và tọa độ quốc gia, nền tảng cho bản đồ địa chính.",en:"VN-2000 is the national reference and coordinate system underlying cadastral maps."}},{q:{vi:"Môi giới đề nghị “hậu tạ” để giữ diện tích theo tờ khai, gồm cả phần lấn ngõ chung. Bạn làm gì?",en:"A broker offers a reward to keep the declared area that includes the encroached alley. What do you do?"},options:{vi:["Đồng ý vì chênh lệch nhỏ","Giữ số tờ khai nhưng không nhận tiền","Chờ hàng xóm khiếu nại","Ghi đúng diện tích đo đạc, từ chối lợi ích và báo cáo"],en:["Agree since the gap is small","Keep the declared figure but refuse the money","Wait for neighbors to complain","Record the surveyed area, refuse the benefit and report it"]},answer:3,explain:{vi:"Hồ sơ địa chính phải đúng thực địa; nhận lợi ích để làm sai là vi phạm pháp luật về phòng, chống tham nhũng.",en:"Cadastral records must match the ground; taking benefits to falsify them breaks anti-corruption law."}}]}},"KK-978":{scenario:{company:"Meridia Plaza Management",supervisor:{name:"Lương Đức Mạnh",role:{vi:"Trưởng ban An toàn Phòng cháy Chữa cháy",en:"Fire Safety Manager"}},ref_code:"PA-3105",title:{vi:"Đúng loại đám cháy. Đủ nước chữa cháy.",en:"Right fire class. Enough fire water."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát phương án chữa cháy PA-3105 của một trung tâm thương mại trước đợt kiểm tra. Khu ẩm thực có 12 chảo chiên ngập dầu ăn công nghiệp. Sprinkler: cường độ phun 0.1 L/s.m2, diện tích tính toán 260 m2, thời gian 60 phút; họng nước chữa cháy trong nhà: 2 họng x 2.5 L/s, thời gian 3 giờ. Sửa loại đám cháy dùng để chọn bình cho khu chiên và dung tích nước dự trữ chữa cháy (m3) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"This is a training scenario. You are reviewing firefighting plan PA-3105 for a shopping mall before an inspection. The food court has 12 commercial deep fryers using cooking oil. Sprinklers: density 0.1 L/s.m2, design area 260 m2, duration 60 minutes; indoor fire hydrants: 2 x 2.5 L/s for 3 hours. Correct the fire class used to choose extinguishers for the fryer area and the fire water reserve (m3) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Phương án chữa cháy & bảng tính nước đã duyệt · PA-3105",en:"Approved fire plan & water calculation · PA-3105"},fields:[{id:"FIRE_CLASS",label:{vi:"Loại đám cháy khu chiên (ISO 3941)",en:"Fryer area fire class (ISO 3941)"},initial:"CLASS-B",expected:"CLASS-F",choices:["CLASS-A","CLASS-B","CLASS-F"],reference:"Bảng phân loại đám cháy và bình",hint:{vi:"Dầu mỡ nấu ăn ở nhiệt độ cao được xếp riêng một loại, cần chất chữa cháy tạo lớp xà phòng hóa, tuyệt đối không dùng nước.",en:"Hot cooking oils and fats form a class of their own and need a saponifying agent; never use water."}},{id:"WATER_M3",label:{vi:"Nước dự trữ chữa cháy (m3)",en:"Fire water reserve (m3)"},initial:"100.8",expected:"147.6",reference:"Bảng tính nước chữa cháy",ref_value:{vi:"Sprinkler 0.1 L/s.m2 x 260 m2 trong 60 phút; họng nước 2 x 2.5 L/s trong 3 giờ",en:"Sprinkler 0.1 L/s.m2 x 260 m2 for 60 min; hydrants 2 x 2.5 L/s for 3 h"},hint:{vi:"Mỗi hệ thống dùng đúng thời gian chữa cháy tính toán của nó; đổi L/s sang m3 qua số giây.",en:"Each system uses its own design duration; convert L/s to m3 through the number of seconds."}}],sop32:{vi:"Nước dự trữ (m3) = (cường độ phun x diện tích tính toán x thời gian sprinkler + số họng x lưu lượng mỗi họng x thời gian họng nước) / 1000, thời gian tính bằng giây (số liệu mô phỏng).",en:"Fire water reserve (m3) = (density x design area x sprinkler duration + hydrants x flow per hydrant x hydrant duration) / 1000, with durations in seconds (simulated)."},context:{label:"FIRE PLAN / PA-3105",metrics:[{label:{vi:"Cường độ phun sprinkler",en:"Sprinkler density"},value:"0.1 L/s.m2"},{label:{vi:"Diện tích tính toán",en:"Design area"},value:"260 m2"},{label:{vi:"Họng nước trong nhà",en:"Indoor hydrants"},value:"2 x 2.5 L/s"}]},crisis:{vi:"Quản lý trung tâm yêu cầu khóa van tổng sprinkler khu ẩm thực vì “hay phun nhầm làm ướt hàng”, đồng thời ký luôn biên bản diễn tập tháng này dù chưa tổ chức, để kịp khai trương cuối tuần.",en:"The mall manager asks you to close the food court sprinkler control valve because it “keeps soaking the stock”, and to sign this month's drill record although no drill was held, to open on time this weekend."},options:{safe:{vi:"Từ chối khóa van và ký khống biên bản, báo giám đốc trung tâm bằng văn bản; gọi đơn vị bảo trì kiểm tra nguyên nhân phun nhầm và tổ chức diễn tập thật trước ngày khai trương.",en:"Refuse to close the valve or sign a false record and inform the mall director in writing; call maintenance to find the cause of the discharges and hold a real drill before opening."},shortcut:{vi:"Khóa van sprinkler khu ẩm thực và ký biên bản diễn tập để kịp khai trương.",en:"Close the food court sprinkler valve and sign the drill record to open on time."},wait:{vi:"Không làm gì, chờ đoàn kiểm tra đến rồi tính tiếp.",en:"Do nothing and deal with it when the inspectors arrive."}},questions:{vi:["Vì sao khu chiên phải xếp CLASS-F? Lượng nước dự trữ 147.6 m3 được tính từ những thông số nào?","Khóa van sprinkler và ký khống biên bản diễn tập gây rủi ro gì về tính mạng và pháp lý? Bạn đề xuất cách xử lý báo phun nhầm thế nào?"],en:["Why must the fryer area be CLASS-F? Which parameters produce the corrected water reserve?","What life safety and legal risks come from closing the valve and signing a false drill record? How would you fix the false discharges?"]},hints:{vi:["Xác định chất cháy chính của khu chiên trước khi chọn loại bình.","Tính riêng lượng nước của từng hệ thống với đúng thời gian ở SOP mục 3.2 rồi cộng lại.","Đọc lại SOP mục 4.2: không vô hiệu hóa hệ thống chữa cháy hay ký khống hồ sơ; báo cáo người có thẩm quyền."],en:["Identify the main fuel in the fryer area before choosing extinguishers.","Compute water for each system with its own duration per SOP 3.2, then add them.","Re-read SOP 4.2: never disable fire systems or sign false records; escalate to the responsible authority."]}},learning:{summary:{vi:"Chuyên viên phòng cháy chữa cháy và cứu nạn điều phối toàn bộ công tác an toàn cháy của cơ sở: lập và thực tập phương án chữa cháy, quản lý hệ thống báo cháy, chữa cháy, lối thoát nạn, huấn luyện lực lượng tại chỗ và chỉ huy ban đầu khi có sự cố. Nghề đòi hỏi nắm chắc quy chuẩn, kỹ thuật, khả năng điều phối và không khoan nhượng với vi phạm.",en:"A fire safety and rescue coordinator runs a facility's whole fire safety program: preparing and drilling the firefighting plan, managing detection, suppression and escape routes, training the on-site team and leading the first response to incidents. The role requires solid codes and technical knowledge, coordination skills and zero tolerance for violations."},responsibilities:{vi:["Lập, cập nhật và tổ chức thực tập phương án chữa cháy, cứu nạn của cơ sở.","Quản lý kiểm tra, bảo trì hệ thống báo cháy, sprinkler, họng nước, bơm và bình chữa cháy.","Kiểm soát lối thoát nạn, ngăn cháy, vật liệu và hoạt động nóng như hàn, cắt.","Huấn luyện đội phòng cháy chữa cháy cơ sở và hướng dẫn khách thuê, người lao động.","Chỉ huy xử lý ban đầu, phối hợp lực lượng chức năng và báo cáo sự cố."],en:["Prepare, update and drill the facility's firefighting and rescue plan.","Manage testing and maintenance of alarms, sprinklers, hydrants, pumps and extinguishers.","Control escape routes, compartmentation, materials and hot work such as welding and cutting.","Train the on-site fire team and brief tenants and staff.","Lead the initial response, coordinate with authorities and report incidents."]},competencies:[{name:{vi:"Quy chuẩn PCCC",en:"Fire codes"},desc:{vi:"Áp dụng quy chuẩn an toàn cháy về thoát nạn, ngăn cháy và trang bị phương tiện.",en:"Apply fire codes on escape, compartmentation and equipment provision."}},{name:{vi:"Hệ thống kỹ thuật",en:"Fire protection systems"},desc:{vi:"Hiểu báo cháy, sprinkler, họng nước, bơm, chất chữa cháy và tính lượng nước.",en:"Understand alarms, sprinklers, hydrants, pumps, agents and water calculations."}},{name:{vi:"Điều phối ứng cứu",en:"Emergency coordination"},desc:{vi:"Tổ chức sơ tán, chỉ huy ban đầu và phối hợp lực lượng chữa cháy chuyên nghiệp.",en:"Run evacuations, lead first response and coordinate with professional firefighters."}},{name:{vi:"Huấn luyện & diễn tập",en:"Training & drills"},desc:{vi:"Thiết kế kịch bản diễn tập sát thực tế và đánh giá thời gian sơ tán.",en:"Design realistic drill scenarios and evaluate evacuation times."}},{name:{vi:"Kiên định an toàn",en:"Safety resolve"},desc:{vi:"Không vô hiệu hóa hệ thống hay ký khống hồ sơ dù chịu áp lực kinh doanh.",en:"Never disable systems or sign false records under business pressure."}}],knowledge:{vi:["Luật Phòng cháy, chữa cháy và cứu nạn, cứu hộ năm 2024 cùng các nghị định, thông tư hướng dẫn.","QCVN 06:2022/BXD về an toàn cháy cho nhà và công trình: lối thoát nạn, ngăn cháy, khoảng cách.","ISO 3941 phân loại đám cháy A, B, C, D, F và nguyên tắc chọn chất chữa cháy tương ứng.","Thiết kế sprinkler, họng nước trong nhà và trang bị bình chữa cháy theo TCVN liên quan, NFPA 13 và NFPA 10.","Quản lý tạm ngừng hệ thống (impairment), canh cháy và bảo trì định kỳ hệ thống báo cháy, chữa cháy."],en:["The 2024 Law on Fire Prevention, Firefighting and Rescue with its decrees and circulars.","QCVN 06:2022/BXD on fire safety of buildings: escape routes, compartmentation and separation.","ISO 3941 fire classes A, B, C, D and F and how to match extinguishing agents.","Design of sprinklers, indoor hydrants and extinguisher provision per relevant TCVN, NFPA 13 and NFPA 10.","Impairment management, fire watch and periodic maintenance of detection and suppression systems."]},tools:["Trung tâm báo cháy địa chỉ","Phần mềm quản lý bảo trì PCCC","Bình chữa cháy các loại (bọt, CO2, hóa chất ướt)","Bơm chữa cháy và đồng hồ thử áp","Phần mềm mô phỏng thoát nạn","Bộ đàm và hệ thống âm thanh sơ tán"],kpis:{vi:["Tỷ lệ hệ thống PCCC ở trạng thái sẵn sàng hoạt động.","Thời gian sơ tán trong diễn tập so với mục tiêu.","Tỷ lệ hạng mục kiểm tra, bảo trì hoàn thành đúng hạn.","Số tồn tại sau kiểm tra của cơ quan chức năng (mục tiêu bằng 0)."],en:["Share of fire systems in ready-to-operate status.","Drill evacuation time versus target.","Share of inspection and maintenance items done on time.","Findings left open after official inspections (target zero)."]},day:[{time:"07:30",vi:"Kiểm tra tủ báo cháy, áp lực bơm, van tổng sprinkler và nhật ký ca đêm.",en:"Check the fire panel, pump pressure, sprinkler control valves and the night log."},{time:"09:00",vi:"Đi tuần lối thoát nạn, cửa ngăn cháy và khu bếp của khách thuê.",en:"Walk escape routes, fire doors and tenant kitchens."},{time:"11:00",vi:"Duyệt giấy phép hoạt động nóng, giám sát nhà thầu thi công.",en:"Approve hot work permits and supervise contractors."},{time:"14:00",vi:"Huấn luyện đội PCCC cơ sở sử dụng bình hóa chất ướt và họng nước.",en:"Train the on-site fire team on wet chemical extinguishers and hydrants."},{time:"16:30",vi:"Cập nhật phương án chữa cháy, hồ sơ bảo trì và báo cáo ban giám đốc.",en:"Update the fire plan and maintenance records and report to management."}],mistakes:{vi:["Xếp đám cháy dầu ăn vào loại B và trang bị bình không phù hợp cho khu bếp.","Tính nước dự trữ với thời gian chữa cháy sai hoặc quên một hệ thống.","Khóa van, tắt báo cháy vì báo giả mà không xử lý nguyên nhân và không có quy trình tạm ngừng."],en:["Classing cooking oil fires as class B and fitting unsuitable extinguishers in kitchens.","Calculating fire water with the wrong duration or leaving out a system.","Closing valves or silencing alarms after false alarms without fixing the cause or following impairment procedures."]},career:[{vi:"Nhân viên đội PCCC cơ sở",en:"On-site fire team member"},{vi:"Chuyên viên phòng cháy chữa cháy và cứu nạn",en:"Fire safety and rescue coordinator"},{vi:"Trưởng ban an toàn PCCC của tổ hợp công trình",en:"Fire safety manager of a complex"},{vi:"Giám đốc an toàn, sức khỏe và môi trường (HSE)",en:"Health, safety and environment (HSE) director"}],glossary:[{term:"Class F",vi:"Đám cháy dầu mỡ nấu ăn theo ISO 3941, cần bình hóa chất ướt.",en:"Cooking oil and fat fires under ISO 3941, requiring wet chemical extinguishers."},{term:"Sprinkler",vi:"Hệ thống chữa cháy tự động bằng đầu phun nước kích hoạt theo nhiệt độ.",en:"Automatic water suppression system with heat-activated heads."},{term:"Họng nước trong nhà",vi:"Điểm lấy nước chữa cháy gắn vòi, lăng phun đặt trong công trình.",en:"Indoor fire hydrant outlets with hoses and nozzles inside the building."},{term:"Impairment",vi:"Tình trạng hệ thống PCCC tạm ngừng hoạt động, phải có quy trình kiểm soát và canh cháy.",en:"A fire system out of service, requiring control procedures and a fire watch."},{term:"Phương án chữa cháy",vi:"Tài liệu kế hoạch tổ chức chữa cháy, sơ tán và phối hợp lực lượng tại cơ sở.",en:"The facility plan for firefighting, evacuation and coordination of responders."}],quiz:[{q:{vi:"Đám cháy chảo chiên ngập dầu ăn trong bếp thuộc loại nào theo ISO 3941?",en:"A deep fryer cooking oil fire belongs to which ISO 3941 class?"},options:{vi:["Loại A","Loại B","Loại C","Loại F"],en:["Class A","Class B","Class C","Class F"]},answer:3,explain:{vi:"Dầu mỡ nấu ăn là loại F, cần bình hóa chất ướt; phun nước gây bùng cháy dữ dội.",en:"Cooking oils and fats are class F and need wet chemical; water causes violent flare-ups."}},{q:{vi:"Sprinkler 0.08 L/s.m2 trên 150 m2 trong 30 phút cần bao nhiêu m3 nước?",en:"Sprinklers at 0.08 L/s.m2 over 150 m2 for 30 minutes need how much water?"},options:{vi:["12 m3","21.6 m3","43.2 m3","7.2 m3"],en:["12 m3","21.6 m3","43.2 m3","7.2 m3"]},answer:1,explain:{vi:"Lưu lượng 0.08 x 150 = 12 L/s; 12 x 1800 giây = 21600 L = 21.6 m3.",en:"Flow 0.08 x 150 = 12 L/s; 12 x 1800 s = 21600 L = 21.6 m3."}},{q:{vi:"Quản lý yêu cầu khóa van sprinkler vì hay phun nhầm. Bạn làm gì?",en:"The manager asks you to close a sprinkler valve because of false discharges. What do you do?"},options:{vi:["Từ chối, báo cáo bằng văn bản và cho kiểm tra nguyên nhân phun nhầm","Khóa van đến khi khai trương xong","Khóa van ban ngày, mở ban đêm","Tháo đầu phun ở khu hay phun"],en:["Refuse, report in writing and have the cause investigated","Close it until after the opening","Close it by day, open at night","Remove the heads that discharge"]},answer:0,explain:{vi:"Vô hiệu hóa sprinkler khiến khu đông người mất bảo vệ; phải xử lý nguyên nhân theo quy trình.",en:"Disabling sprinklers leaves a crowded area unprotected; fix the cause through proper procedures."}},{q:{vi:"Khi chuông báo cháy kêu trong trung tâm thương mại, hướng dẫn sơ tán đúng là gì?",en:"When the fire alarm sounds in a mall, what is the correct evacuation guidance?"},options:{vi:["Dùng thang máy cho nhanh","Quay lại lấy đồ cá nhân","Đi theo lối thoát nạn, dùng thang bộ, không dùng thang máy","Chờ trong cửa hàng đến khi có thông báo"],en:["Use the lifts to be quick","Go back for belongings","Follow escape routes and stairs, never the lifts","Wait in the shop for an announcement"]},answer:2,explain:{vi:"Thang máy có thể dừng hoặc mở ra tầng cháy; phải sơ tán theo lối thoát nạn và thang bộ.",en:"Lifts may stop or open onto the fire floor; evacuate via escape routes and stairs."}}]}},"KK-979":{scenario:{company:"Bình Nguyên Logistics Hub",supervisor:{name:"Quách Thế Vinh",role:{vi:"Giám đốc Rủi ro & Tuân thủ",en:"Chief Risk & Compliance Officer"}},ref_code:"SEC-4417",title:{vi:"Đúng mức sự cố. Đủ người trực. Giữ nguyên chứng cứ.",en:"Right severity. Enough guards. Evidence intact."},brief:{vi:"Đây là tình huống đào tạo. Lúc 02:10 camera ghi nhận một người lạ bám đuôi qua cổng thẻ vào lồng hàng giá trị cao của kho B và lấy đi 2 thùng linh kiện (thiệt hại mô phỏng 380 triệu đồng). Bản nháp báo cáo SEC-4417 xếp sự cố mức SEV-3 và đề xuất 15 bảo vệ cho 5 chốt trực 24/7 sau sự cố. Đối chiếu với ma trận sự cố đã duyệt, sửa mức độ sự cố và số bảo vệ cần bố trí, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. At 02:10 CCTV recorded an unknown person tailgating through the card gate into the high-value cage of warehouse B and removing 2 cartons of components (training loss 380 million VND). Draft report SEC-4417 rates the incident SEV-3 and proposes 15 guards for 5 posts staffed 24/7 after the incident. Compare it with the approved incident matrix, correct the severity and the guard headcount, then write an evidence-based report."},reference_title:{vi:"Ma trận sự cố & định biên an ninh đã duyệt · SEC-4417",en:"Approved incident matrix & security staffing · SEC-4417"},fields:[{id:"INC_SEV",label:{vi:"Mức độ sự cố",en:"Incident severity"},initial:"SEV-3",expected:"SEV-1",choices:["SEV-1","SEV-2","SEV-3"],reference:"Ma trận phân loại sự cố an ninh",hint:{vi:"Đã có xâm nhập vùng hạn chế và mất tài sản thật: ma trận xếp vào mức cao nhất, không phải vi phạm nội quy thông thường.",en:"There was a real intrusion into a restricted zone with actual loss: the matrix puts it at the top level, not a routine policy breach."}},{id:"GUARD_FTE",label:{vi:"Số bảo vệ cần bố trí (người)",en:"Guards required (headcount)"},initial:"15",expected:"18",reference:"Bảng định biên chốt trực",ref_value:{vi:"5 chốt trực 24 giờ x 7 ngày; giờ làm việc bình thường tối đa 48 giờ/người/tuần",en:"5 posts staffed 24 hours x 7 days; normal working time max 48 hours per guard per week"},hint:{vi:"Đừng lấy số chốt nhân 3 ca: mỗi người chỉ làm 48 giờ/tuần, hãy tính tổng giờ trực rồi chia và làm tròn lên.",en:"Do not multiply posts by 3 shifts: each guard works only 48 hours a week, so total the post-hours, divide and round up."}}],sop32:{vi:"Số bảo vệ cần = tổng giờ trực của các chốt trong tuần ÷ 48 giờ/người/tuần, làm tròn lên số nguyên; chưa tính dự phòng nghỉ phép (quy tắc mô phỏng).",en:"Guards required = total weekly post-hours ÷ 48 hours per guard per week, rounded up to a whole number; leave relief not included (training rule)."},context:{label:"SOC / SEC-4417",metrics:[{label:{vi:"Chốt trực 24/7",en:"Posts staffed 24/7"},value:"5"},{label:{vi:"Giờ chuẩn mỗi người/tuần",en:"Standard hours per guard/week"},value:"48 h"},{label:{vi:"Thiệt hại mô phỏng",en:"Training loss"},value:"380,000,000 VND"}]},crisis:{vi:"Đội trưởng nhà thầu bảo vệ nhắn: “Anh ghi SEV-3 giúp em, coi như hao hụt do kiểm đếm. Em sẽ cho xóa đoạn camera đêm qua, cuối tháng có quà cảm ơn. Khách hàng mà biết thì bên em mất hợp đồng.”",en:"The guard contractor's team leader texts: “Please log it as SEV-3, call it a stock count shortfall. I'll have last night's footage deleted and there's a thank-you gift at month end. If the client finds out we lose the contract.”"},options:{safe:{vi:"Giữ mức SEV-1, khóa và sao lưu đoạn camera làm chứng cứ, từ chối quà, báo Giám đốc Rủi ro và khách hàng theo hợp đồng, phối hợp công an điều tra.",en:"Keep SEV-1, lock and back up the footage as evidence, decline the gift, report to the Chief Risk Officer and the client per contract, and support the police investigation."},shortcut:{vi:"Ghi SEV-3 và để nhà thầu xóa đoạn camera cho êm chuyện, tự bù hàng sau.",en:"Log SEV-3, let the contractor delete the footage to keep things quiet and replace the stock later."},wait:{vi:"Chưa xử lý gì, chờ nhà thầu tự điều tra rồi báo lại.",en:"Do nothing for now and wait for the contractor to investigate and report back."}},questions:{vi:["Vì sao sự cố phải xếp SEV-1 chứ không phải SEV-3? Dữ kiện nào từ camera và ma trận chứng minh điều đó?","Bạn tính số bảo vệ cần bố trí thế nào, và xử lý ra sao trước đề nghị xóa camera kèm quà của nhà thầu?"],en:["Why must the incident be rated SEV-1 rather than SEV-3? Which CCTV facts and matrix rules prove it?","How did you calculate the guard headcount, and how do you handle the contractor's offer to delete footage in exchange for a gift?"]},hints:{vi:["Đặt bản nháp cạnh ma trận sự cố và đánh dấu dòng mức độ đang bị hạ thấp.","Tính tổng giờ trực trong tuần của các chốt rồi áp dụng SOP mục 3.2, nhớ làm tròn lên.","Đọc lại SOP mục 4.2: chứng cứ sự cố phải được bảo toàn, mọi đề nghị che giấu phải báo cáo cấp trên."],en:["Place the draft next to the incident matrix and flag the severity line that was downgraded.","Total the weekly post-hours, apply SOP 3.2 and remember to round up.","Re-read SOP 4.2: incident evidence must be preserved and any request to conceal must be escalated."]}},learning:{summary:{vi:"Quản lý an ninh doanh nghiệp xây dựng và vận hành hệ thống bảo vệ con người, tài sản, thông tin và hoạt động kinh doanh: đánh giá rủi ro an ninh, thiết kế phân vùng và kiểm soát ra vào, giám sát camera, định biên bảo vệ, quản lý nhà thầu và điều tra sự cố. Nghề đòi hỏi tư duy rủi ro, hiểu pháp luật lao động và dữ liệu cá nhân, phối hợp tốt với cơ quan công an và giữ liêm chính tuyệt đối khi xử lý chứng cứ.",en:"A corporate security manager builds and runs the protection of people, assets, information and operations: security risk assessment, zoning and access control, CCTV monitoring, guard staffing, contractor management and incident investigation. The role requires risk thinking, knowledge of labour and personal data law, close cooperation with the police and absolute integrity when handling evidence."},responsibilities:{vi:["Đánh giá rủi ro an ninh định kỳ cho từng khu vực, tài sản và quy trình trọng yếu.","Thiết kế phân vùng, kiểm soát ra vào, camera và báo động tương xứng với mức trọng yếu của tài sản.","Lập định biên, lịch trực và giám sát chất lượng nhà thầu bảo vệ theo cam kết dịch vụ (SLA).","Tiếp nhận, phân loại, điều tra sự cố, bảo toàn chứng cứ và phối hợp với cơ quan công an.","Xây dựng kế hoạch ứng phó khẩn cấp, tổ chức diễn tập và đào tạo nhận thức an ninh cho nhân viên."],en:["Run periodic security risk assessments for each zone, critical asset and process.","Design zoning, access control, CCTV and alarms in proportion to asset criticality.","Plan headcount and rosters and monitor guard contractor performance against the SLA.","Receive, classify and investigate incidents, preserve evidence and cooperate with the police.","Build emergency response plans, run drills and deliver security awareness training to staff."]},competencies:[{name:{vi:"Đánh giá rủi ro an ninh",en:"Security risk assessment"},desc:{vi:"Nhận diện mối đe dọa, lỗ hổng, hậu quả và xếp hạng rủi ro bằng ma trận khả năng x tác động.",en:"Identify threats, vulnerabilities and consequences and rank risks with a likelihood x impact matrix."}},{name:{vi:"Thiết kế kiểm soát vật lý",en:"Physical control design"},desc:{vi:"Bố trí lớp bảo vệ nhiều tầng: rào, cổng, thẻ, camera, báo động và tuần tra, chống bám đuôi.",en:"Layer defences: fences, gates, cards, CCTV, alarms and patrols, including anti-tailgating measures."}},{name:{vi:"Điều tra & quản lý chứng cứ",en:"Investigation & evidence handling"},desc:{vi:"Thu thập, niêm phong, lưu giữ chứng cứ theo chuỗi lưu giữ để có giá trị khi chuyển cơ quan chức năng.",en:"Collect, seal and store evidence under chain of custody so it stays valid when handed to authorities."}},{name:{vi:"Quản lý nhà thầu & định biên",en:"Contractor & staffing management"},desc:{vi:"Tính định biên đúng giới hạn giờ làm, giám sát SLA, xử phạt và cải tiến dịch vụ bảo vệ thuê ngoài.",en:"Size headcount within working time limits, monitor SLAs, apply penalties and improve outsourced guarding."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Từ chối che giấu sự cố, không nhận quà từ nhà thầu, tôn trọng quyền riêng tư và dữ liệu cá nhân.",en:"Refuse to conceal incidents, accept no gifts from contractors and respect privacy and personal data."}}],knowledge:{vi:["ISO 31000 về quản lý rủi ro: nhận diện, phân tích, đánh giá và xử lý rủi ro.","ISO 28000 về hệ thống quản lý an ninh chuỗi cung ứng và ISO 22301 về quản lý kinh doanh liên tục.","Bộ luật Lao động 2019: giờ làm việc bình thường không quá 8 giờ/ngày và 48 giờ/tuần, có giới hạn làm thêm giờ.","Pháp luật hiện hành về bảo vệ dữ liệu cá nhân, áp dụng cho hình ảnh camera và nhật ký ra vào.","Quy định về điều kiện an ninh, trật tự đối với doanh nghiệp kinh doanh dịch vụ bảo vệ khi thuê ngoài.","Phương pháp phòng ngừa tội phạm qua thiết kế môi trường (CPTED) và nguyên tắc chuỗi lưu giữ chứng cứ."],en:["ISO 31000 on risk management: identifying, analysing, evaluating and treating risk.","ISO 28000 on supply chain security management systems and ISO 22301 on business continuity management.","Vietnam Labour Code 2019: normal working time up to 8 hours a day and 48 hours a week, with overtime limits.","Current personal data protection law, which applies to CCTV images and access logs.","Regulations on security and order conditions for licensed guarding service providers.","Crime Prevention Through Environmental Design (CPTED) and chain of custody principles."]},tools:["Hệ thống quản lý video (VMS)","Hệ thống kiểm soát ra vào (ACS)","Phần mềm quản lý sự cố an ninh","Sổ đăng ký & ma trận rủi ro","Ứng dụng tuần tra điện tử và bộ đàm","Bảng tính định biên"],kpis:{vi:["Thời gian từ lúc báo động đến khi có người tại hiện trường.","Tỷ lệ sự cố được phân loại và báo cáo đúng hạn theo ma trận.","Tỷ lệ chốt trực đủ quân số, tuần tra đúng tuyến và đúng giờ.","Tổn thất do mất cắp so với giá trị hàng lưu kho."],en:["Time from alarm to a guard on scene.","Share of incidents classified and reported on time per the matrix.","Share of posts fully staffed and patrols completed on route and on time.","Theft losses as a share of stored inventory value."]},day:[{time:"07:30",vi:"Nhận bàn giao ca đêm, xem nhật ký sự cố và cảnh báo từ trung tâm giám sát.",en:"Take the night shift handover, review the incident log and monitoring alerts."},{time:"09:00",vi:"Họp nhanh với nhà thầu bảo vệ, kiểm tra quân số và chất lượng tuần tra.",en:"Hold a stand-up with the guard contractor and check headcount and patrol quality."},{time:"11:00",vi:"Rà soát quyền thẻ vào vùng hạn chế, thu hồi thẻ của người đã nghỉ việc.",en:"Review restricted zone card rights and revoke cards of leavers."},{time:"14:00",vi:"Điều tra sự cố, trích xuất và niêm phong dữ liệu camera theo chuỗi lưu giữ.",en:"Investigate an incident, export and seal CCTV data under chain of custody."},{time:"16:30",vi:"Cập nhật sổ đăng ký rủi ro và báo cáo lãnh đạo biện pháp khắc phục.",en:"Update the risk register and report corrective actions to management."}],mistakes:{vi:["Hạ mức độ sự cố để tránh ảnh hưởng hợp đồng hoặc KPI, làm mất cơ hội xử lý nguyên nhân gốc.","Định biên bằng số chốt nhân số ca, khiến bảo vệ làm vượt giờ và chốt bị bỏ trống.","Để dữ liệu camera bị ghi đè hoặc chỉnh sửa trước khi trích xuất, làm mất giá trị chứng cứ."],en:["Downgrading incidents to protect a contract or KPI, losing the chance to fix the root cause.","Sizing headcount as posts times shifts, which causes excessive hours and empty posts.","Letting CCTV data be overwritten or edited before export, destroying its value as evidence."]},career:[{vi:"Nhân viên giám sát an ninh",en:"Security monitoring officer"},{vi:"Trưởng ca trung tâm giám sát an ninh",en:"Security operations shift lead"},{vi:"Quản lý an ninh doanh nghiệp",en:"Corporate security manager"},{vi:"Giám đốc an ninh & rủi ro (CSO)",en:"Chief Security Officer (CSO)"}],glossary:[{term:"Tailgating",vi:"Hành vi bám sát người có thẻ để đi qua cửa kiểm soát mà không xác thực.",en:"Following an authorised person through a controlled door without authenticating."},{term:"Chain of custody",vi:"Hồ sơ ghi nhận ai thu giữ, chuyển giao, lưu trữ chứng cứ và vào thời điểm nào.",en:"Record of who seized, transferred and stored evidence, and when."},{term:"SOC",vi:"Trung tâm điều hành an ninh, nơi giám sát camera, báo động và điều phối ứng phó.",en:"Security operations centre that monitors CCTV and alarms and coordinates response."},{term:"CPTED",vi:"Phòng ngừa tội phạm bằng thiết kế không gian: chiếu sáng, tầm nhìn, ranh giới, kiểm soát lối đi.",en:"Crime prevention through design of space: lighting, sightlines, boundaries and access control."},{term:"SLA",vi:"Cam kết mức dịch vụ giữa doanh nghiệp và nhà thầu, kèm chỉ số đo và chế tài.",en:"Service level agreement between the company and a contractor, with metrics and penalties."}],quiz:[{q:{vi:"Kho có 4 chốt trực 24/7, mỗi bảo vệ làm 48 giờ/tuần. Cần tối thiểu bao nhiêu người (chưa tính dự phòng)?",en:"A warehouse has 4 posts staffed 24/7 and each guard works 48 hours a week. What is the minimum headcount (excluding relief)?"},options:{vi:["12 người","14 người","16 người","8 người"],en:["12 guards","14 guards","16 guards","8 guards"]},answer:1,explain:{vi:"4 x 168 = 672 giờ trực/tuần; 672 ÷ 48 = 14 người.",en:"4 x 168 = 672 post-hours per week; 672 ÷ 48 = 14 guards."}},{q:{vi:"Kẻ gian bám đuôi qua cửa thẻ là lỗ hổng của lớp kiểm soát nào?",en:"Tailgating through a card door exposes a weakness in which control layer?"},options:{vi:["Kiểm soát an ninh mạng","Kiểm soát kế toán","Kiểm soát nhân sự tuyển dụng","Kiểm soát ra vào vật lý"],en:["Cyber security control","Accounting control","Recruitment control","Physical access control"]},answer:3,explain:{vi:"Bám đuôi vượt qua cửa kiểm soát ra vào; cần cửa xoay một người, cảnh báo cửa mở lâu và đào tạo nhân viên.",en:"Tailgating defeats access control; use single-person turnstiles, door-held alarms and staff training."}},{q:{vi:"Nhà thầu đề nghị xóa camera để che sự cố và hứa có quà. Bạn làm gì?",en:"A contractor offers a gift if you delete footage to hide an incident. What do you do?"},options:{vi:["Từ chối, bảo toàn dữ liệu và báo cáo lãnh đạo, khách hàng","Đồng ý vì thiệt hại nhỏ","Xóa một phần đoạn camera","Im lặng và chờ nhà thầu tự xử lý"],en:["Refuse, preserve the data and report to management and the client","Agree because the loss is small","Delete part of the footage","Stay silent and let the contractor handle it"]},answer:0,explain:{vi:"Che giấu sự cố và hủy chứng cứ là vi phạm nghiêm trọng; phải giữ chứng cứ và báo cáo người có thẩm quyền.",en:"Concealing incidents and destroying evidence is a serious violation; preserve evidence and report to those in authority."}},{q:{vi:"Nguyên tắc chuỗi lưu giữ chứng cứ yêu cầu điều gì?",en:"What does the chain of custody principle require?"},options:{vi:["Chỉ cần lưu bản sao trên điện thoại","Cho mọi người xem để xác minh","Ghi nhận đầy đủ người, thời điểm thu giữ, chuyển giao và lưu trữ","Chỉnh sửa video cho rõ hơn rồi lưu"],en:["Keep a copy on a phone only","Let everyone view it to verify","Record who seized, transferred and stored it and when","Enhance the video before saving it"]},answer:2,explain:{vi:"Chứng cứ chỉ có giá trị khi chứng minh được không bị thay đổi qua từng lần chuyển giao.",en:"Evidence is only valid if it can be shown to be unchanged through every transfer."}}]}},"KK-980":{scenario:{company:"Tòa án Mô phỏng Đông Phong",supervisor:{name:"Lê Thị Bích Ngọc",role:{vi:"Thẩm phán chủ tọa",en:"Presiding Judge"}},ref_code:"TBTU-0526",title:{vi:"Đúng loại vụ án. Đúng tạm ứng án phí. Đúng ngày nhận.",en:"Right case type. Right advance fee. True filing date."},brief:{vi:"Đây là tình huống đào tạo. Công ty A khởi kiện Công ty B (cả hai có đăng ký kinh doanh, cùng mục đích lợi nhuận) đòi 620 triệu đồng tiền hàng theo hợp đồng mua bán. Bản nháp thông báo nộp tạm ứng án phí TBTU-0526 ghi loại vụ án DS và số tiền tạm ứng 28800000 đồng. Đối chiếu hồ sơ thụ lý đã duyệt, sửa loại vụ án và số tiền tạm ứng án phí theo biểu mức mô phỏng, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. Company A sues Company B (both registered businesses seeking profit) for 620 million VND owed under a sales contract. Draft advance fee notice TBTU-0526 records case type DS and an advance of 28800000 VND. Compare it with the approved case intake file, correct the case type and the advance court fee using the training fee scale, then write an evidence-based report."},reference_title:{vi:"Hồ sơ thụ lý & bảng tính án phí đã duyệt · TBTU-0526",en:"Approved case intake & court fee worksheet · TBTU-0526"},fields:[{id:"CASE_TYPE",label:{vi:"Loại vụ án (ký hiệu)",en:"Case type (code)"},initial:"DS",expected:"KDTM",choices:["DS","KDTM","HC"],reference:"Quyết định phân loại thụ lý",hint:{vi:"Tranh chấp phát sinh trong hoạt động kinh doanh giữa các bên có đăng ký kinh doanh, cùng mục đích lợi nhuận là vụ án kinh doanh, thương mại.",en:"A dispute from business activity between registered businesses that both seek profit is a business and commercial case."}},{id:"ADV_FEE",label:{vi:"Tạm ứng án phí sơ thẩm (VND)",en:"First-instance advance fee (VND)"},initial:"28800000",expected:"14400000",reference:"Bảng tính án phí",ref_value:{vi:"Giá ngạch 620 triệu đồng; biểu mô phỏng trên 400-800 triệu: 20 triệu + 4% phần vượt 400 triệu",en:"Claim value 620 million VND; training scale over 400-800 million: 20 million + 4% of the excess over 400 million"},hint:{vi:"Bản nháp đang ghi toàn bộ án phí dự tính; tạm ứng chỉ bằng một tỷ lệ của án phí theo SOP mục 3.2.",en:"The draft shows the full estimated fee; the advance is only a share of it per SOP 3.2."}}],sop32:{vi:"Án phí sơ thẩm có giá ngạch tính theo biểu mức mô phỏng trong tài liệu gốc; tạm ứng án phí sơ thẩm = 50% án phí sơ thẩm dự tính trên giá trị tranh chấp nguyên đơn yêu cầu.",en:"The first-instance fee on a monetary claim follows the training scale in the reference file; the first-instance advance = 50% of the estimated first-instance fee on the value claimed by the plaintiff."},context:{label:"SỔ THỤ LÝ / TBTU-0526",metrics:[{label:{vi:"Giá ngạch tranh chấp",en:"Claim value"},value:"620,000,000 VND"},{label:{vi:"Biểu mô phỏng 400-800 triệu",en:"Training scale 400-800 m"},value:"20 m + 4% excess"},{label:{vi:"Tỷ lệ tạm ứng",en:"Advance ratio"},value:"50%"}]},crisis:{vi:"Người đại diện nguyên đơn gọi: “Bên tôi nộp biên lai tạm ứng trễ 2 ngày so với hạn. Chị ghi lùi ngày nhận giúp, tôi gửi chút cà phê cảm ơn, không thì hồ sơ bị trả lại mất.”",en:"The plaintiff's representative calls: “We submitted the advance fee receipt 2 days late. Please backdate the receipt date, I'll send a little coffee money as thanks, otherwise the petition will be returned.”"},options:{safe:{vi:"Từ chối, ghi đúng ngày thực nhận vào sổ, báo Thẩm phán và Chánh án về lời đề nghị, hướng dẫn đương sự trình bày lý do chậm nộp bằng văn bản theo thủ tục.",en:"Refuse, record the actual receipt date, report the offer to the judge and the Chief Judge, and guide the party to explain the delay in writing through the proper procedure."},shortcut:{vi:"Ghi lùi ngày nhận 2 ngày cho kịp hạn vì tiền tạm ứng đã nộp đủ.",en:"Backdate the receipt by 2 days to meet the deadline since the advance was paid in full."},wait:{vi:"Không trả lời, để hồ sơ đó chờ Thẩm phán tự phát hiện.",en:"Do not respond and leave the file until the judge notices it."}},questions:{vi:["Vì sao vụ án phải ký hiệu KDTM chứ không phải DS? Tình tiết nào trong hồ sơ cho thấy điều đó?","Trình bày cách tính tạm ứng án phí và cách bạn xử lý đề nghị ghi lùi ngày nhận biên lai kèm quà cảm ơn."],en:["Why must the case be coded KDTM rather than DS? Which facts in the file show this?","Explain how you calculated the advance fee and how you handle the request to backdate the receipt in exchange for a gift."]},hints:{vi:["Đối chiếu tư cách hai bên và mục đích giao dịch với quyết định phân loại thụ lý.","Tính án phí dự tính theo biểu mô phỏng trước, sau đó áp dụng tỷ lệ tạm ứng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: ngày tháng trong sổ thụ lý phải đúng thực tế, mọi lời mời quà phải báo cáo."],en:["Compare the parties' status and the purpose of the transaction with the intake classification decision.","Calculate the estimated fee on the training scale first, then apply the advance ratio in SOP 3.2.","Re-read SOP 4.2: dates in the intake register must be true and every offer of a gift must be reported."]}},learning:{summary:{vi:"Thư ký Tòa án hỗ trợ Thẩm phán trong toàn bộ quá trình giải quyết vụ việc: tiếp nhận và kiểm tra đơn, vào sổ thụ lý, lập thông báo nộp tạm ứng án phí, tống đạt văn bản tố tụng, chuẩn bị phiên tòa, ghi biên bản phiên tòa và quản lý hồ sơ vụ án. Nghề đòi hỏi nắm chắc thủ tục tố tụng, chính xác tuyệt đối về thời hạn, ngày tháng, số tiền và giữ khách quan, liêm chính trước mọi lời nhờ vả.",en:"A court clerk supports the judge throughout a case: receiving and checking petitions, entering them in the intake register, issuing advance fee notices, serving procedural documents, preparing hearings, keeping the hearing record and managing the case file. The role demands solid procedural knowledge, absolute accuracy on deadlines, dates and amounts, and impartial integrity in the face of any favour seeking."},responsibilities:{vi:["Tiếp nhận đơn khởi kiện, kiểm tra tài liệu kèm theo và vào sổ đúng ngày thực nhận.","Lập thông báo nộp tạm ứng án phí, theo dõi biên lai và thời hạn nộp của đương sự.","Tống đạt, thông báo văn bản tố tụng cho đương sự và lưu bằng chứng tống đạt hợp lệ.","Chuẩn bị phiên tòa, kiểm tra sự có mặt của người tham gia tố tụng và ghi biên bản phiên tòa trung thực.","Sắp xếp, đánh số bút lục hồ sơ vụ án và bàn giao lưu trữ đúng quy định."],en:["Receive petitions, check attached documents and register them on the actual date received.","Issue advance fee notices and track receipts and payment deadlines.","Serve procedural documents on the parties and keep valid proof of service.","Prepare hearings, check attendance of participants and keep a truthful hearing record.","Arrange and paginate the case file and hand it over to the archive as required."]},competencies:[{name:{vi:"Thủ tục tố tụng",en:"Court procedure"},desc:{vi:"Áp dụng đúng trình tự khởi kiện, thụ lý, hòa giải, xét xử và các văn bản tố tụng tương ứng.",en:"Apply the correct sequence of filing, intake, mediation and trial and the matching procedural documents."}},{name:{vi:"Quản lý thời hạn",en:"Deadline management"},desc:{vi:"Theo dõi thời hạn nộp tạm ứng, tống đạt, chuẩn bị xét xử và kháng cáo không để sót.",en:"Track deadlines for advance fees, service, trial preparation and appeals without misses."}},{name:{vi:"Ghi biên bản chính xác",en:"Accurate record keeping"},desc:{vi:"Ghi đầy đủ, trung thực diễn biến phiên tòa, lời khai và ý kiến của người tham gia tố tụng.",en:"Record hearing events, testimony and participants' statements fully and truthfully."}},{name:{vi:"Quản lý hồ sơ & bút lục",en:"Case file management"},desc:{vi:"Sắp xếp tài liệu theo trình tự, đánh bút lục, số hóa và bảo quản hồ sơ an toàn.",en:"Order documents, paginate, digitise and store case files securely."}},{name:{vi:"Liêm chính & bảo mật",en:"Integrity & confidentiality"},desc:{vi:"Không nhận quà, không tiết lộ thông tin vụ án, báo cáo ngay mọi hành vi tác động trái phép.",en:"Accept no gifts, disclose no case information and report any improper influence at once."}}],knowledge:{vi:["Bộ luật Tố tụng dân sự 2015 về thẩm quyền, thụ lý, tống đạt, thời hạn tố tụng và kháng cáo.","Phân loại tranh chấp dân sự, hôn nhân và gia đình, kinh doanh thương mại, lao động theo Bộ luật Tố tụng dân sự.","Nghị quyết 326/2016/UBTVQH14 về mức thu, miễn, giảm, thu, nộp, quản lý và sử dụng án phí, lệ phí Tòa án.","Bộ luật Tố tụng hình sự 2015 và Luật Tố tụng hành chính 2015 đối với các loại vụ án khác.","Quy định về văn thư, lưu trữ hồ sơ vụ án và bảo vệ bí mật trong hoạt động xét xử."],en:["Civil Procedure Code 2015 on jurisdiction, intake, service, procedural deadlines and appeals.","Classification of civil, marriage and family, business and commercial, and labour disputes under the Civil Procedure Code.","Resolution 326/2016/UBTVQH14 on the collection, exemption, reduction and management of court fees and charges.","Criminal Procedure Code 2015 and Law on Administrative Procedure 2015 for other case types.","Rules on records, case file archiving and protection of secrets in adjudication."]},tools:["Phần mềm quản lý án","Sổ thụ lý điện tử","Hệ thống ghi âm, ghi hình phiên tòa","Mẫu văn bản tố tụng","Máy scan & số hóa hồ sơ"],kpis:{vi:["Tỷ lệ văn bản tố tụng được tống đạt đúng hạn, có bằng chứng hợp lệ.","Số lỗi ngày tháng, số tiền, tên đương sự trong văn bản (mục tiêu bằng 0).","Thời gian hoàn thiện biên bản sau khi kết thúc phiên tòa.","Tỷ lệ hồ sơ được đánh bút lục và bàn giao lưu trữ đúng hạn."],en:["Share of procedural documents served on time with valid proof.","Errors in dates, amounts or party names in documents (target zero).","Time to finalise the record after a hearing ends.","Share of case files paginated and archived on time."]},day:[{time:"07:30",vi:"Kiểm tra lịch xét xử, chuẩn bị hồ sơ và danh sách người được triệu tập.",en:"Check the hearing schedule and prepare files and the list of people summoned."},{time:"08:30",vi:"Tiếp nhận đơn, tài liệu mới, vào sổ thụ lý và đóng dấu ngày nhận.",en:"Receive new petitions and documents, register them and stamp the date received."},{time:"10:00",vi:"Ghi biên bản phiên hòa giải hoặc phiên tòa theo diễn biến thực tế.",en:"Keep the record of a mediation session or hearing as it happens."},{time:"14:00",vi:"Soạn thông báo tạm ứng án phí, giấy triệu tập và tổ chức tống đạt.",en:"Draft advance fee notices and summonses and arrange service."},{time:"16:30",vi:"Sắp xếp bút lục, cập nhật phần mềm quản lý án và báo cáo Thẩm phán.",en:"Paginate files, update the case management system and report to the judge."}],mistakes:{vi:["Xếp sai loại vụ án, dẫn tới áp sai biểu án phí và sai cơ quan, thủ tục giải quyết.","Ghi toàn bộ án phí dự tính vào thông báo thay vì mức tạm ứng theo quy định.","Sửa ngày nhận hoặc nội dung biên bản theo yêu cầu đương sự, vi phạm nghiêm trọng pháp luật."],en:["Misclassifying the case type, leading to the wrong fee scale and wrong handling procedure.","Entering the full estimated fee in the notice instead of the required advance amount.","Changing receipt dates or record content at a party's request, a serious breach of the law."]},career:[{vi:"Thư ký Tòa án tập sự",en:"Trainee court clerk"},{vi:"Thư ký Tòa án",en:"Court clerk"},{vi:"Thư ký viên chính",en:"Senior court clerk"},{vi:"Thẩm tra viên hoặc Thẩm phán (qua đào tạo, thi tuyển)",en:"Court examiner or judge (after training and selection)"}],glossary:[{term:"Thụ lý",vi:"Tòa án vào sổ nhận giải quyết vụ án sau khi người khởi kiện nộp biên lai tạm ứng án phí.",en:"Court registration of a case for resolution after the plaintiff submits the advance fee receipt."},{term:"Tống đạt",vi:"Việc giao văn bản tố tụng cho người tham gia tố tụng theo phương thức luật định, có bằng chứng.",en:"Delivery of procedural documents to participants by a lawful method with proof."},{term:"Án phí có giá ngạch",vi:"Án phí tính theo tỷ lệ hoặc biểu mức dựa trên giá trị tài sản tranh chấp.",en:"Court fee calculated by rate or scale on the value of the disputed property."},{term:"Bút lục",vi:"Số thứ tự đánh trên từng trang tài liệu trong hồ sơ vụ án để quản lý và tra cứu.",en:"Sequential page number marked on each document in a case file for control and lookup."},{term:"Kháng cáo",vi:"Quyền của đương sự đề nghị Tòa án cấp trên xét xử phúc thẩm bản án, quyết định sơ thẩm.",en:"A party's right to ask a higher court to review a first-instance judgment or decision on appeal."}],quiz:[{q:{vi:"Theo biểu mô phỏng (trên 400-800 triệu: 20 triệu + 4% phần vượt 400 triệu), tranh chấp 500 triệu đồng có tạm ứng án phí sơ thẩm là bao nhiêu?",en:"On the training scale (over 400-800 million: 20 million + 4% of the excess over 400 million), what is the advance fee for a 500 million VND claim?"},options:{vi:["24 triệu đồng","12 triệu đồng","20 triệu đồng","10 triệu đồng"],en:["24 million VND","12 million VND","20 million VND","10 million VND"]},answer:1,explain:{vi:"Án phí dự tính = 20 + 4% x 100 = 24 triệu; tạm ứng bằng 50% = 12 triệu đồng.",en:"Estimated fee = 20 + 4% x 100 = 24 million; the advance is 50% = 12 million VND."}},{q:{vi:"Tranh chấp hợp đồng mua bán hàng giữa hai công ty cùng mục đích lợi nhuận thuộc loại vụ án nào?",en:"A sales contract dispute between two profit-seeking companies is which case type?"},options:{vi:["Dân sự","Hành chính","Lao động","Kinh doanh, thương mại"],en:["Civil","Administrative","Labour","Business and commercial"]},answer:3,explain:{vi:"Tranh chấp trong hoạt động kinh doanh giữa các bên có đăng ký kinh doanh, cùng mục đích lợi nhuận là vụ án kinh doanh, thương mại.",en:"Disputes from business activity between registered businesses that seek profit are business and commercial cases."}},{q:{vi:"Đương sự đề nghị ghi lùi ngày nhận biên lai và hứa gửi quà cảm ơn. Bạn làm gì?",en:"A party asks you to backdate a receipt and promises a thank-you gift. What do you do?"},options:{vi:["Ghi lùi vì chỉ trễ 2 ngày","Nhận quà nhưng không ghi lùi","Từ chối, ghi đúng ngày và báo cáo lãnh đạo Tòa án","Im lặng và để hồ sơ tồn lại"],en:["Backdate it since it is only 2 days","Take the gift but do not backdate","Refuse, record the true date and report to court leadership","Stay silent and leave the file pending"]},answer:2,explain:{vi:"Sửa ngày trong sổ thụ lý là làm sai lệch hồ sơ; phải ghi đúng thực tế, từ chối quà và báo cáo.",en:"Changing register dates falsifies the record; record the truth, refuse the gift and report it."}},{q:{vi:"Biên bản phiên tòa phải được lập như thế nào?",en:"How must the hearing record be kept?"},options:{vi:["Ghi trung thực, đầy đủ diễn biến; người tham gia được xem và yêu cầu ghi sửa đổi, bổ sung","Chỉ ghi kết luận của Thẩm phán","Ghi tóm tắt sau khi phiên tòa kết thúc vài ngày","Ghi theo bản tự khai của các bên"],en:["Truthfully and fully; participants may read it and request corrections or additions","Only the judge's conclusions","A summary written days after the hearing","Based on the parties' written statements"]},answer:0,explain:{vi:"Biên bản phiên tòa là tài liệu tố tụng quan trọng, phải phản ánh trung thực diễn biến và cho phép người tham gia đề nghị sửa đổi, bổ sung.",en:"The hearing record is a key procedural document; it must reflect events truthfully and allow participants to request corrections."}}]}},"KK-981":{scenario:{company:"Văn phòng Công chứng Lam Kiều",supervisor:{name:"Cao Diệu Linh",role:{vi:"Công chứng viên, Trưởng văn phòng",en:"Notary Public, Head of Office"}},ref_code:"HDCN-1207",title:{vi:"Đủ người ký. Đúng giá tính phí. Ký trước mặt công chứng viên.",en:"All owners sign. Correct fee base. Signed before the notary."},brief:{vi:"Đây là tình huống đào tạo. Ông Hưng kết hôn năm 2015, không có thỏa thuận tài sản; năm 2019 ông nhận chuyển nhượng thửa đất 120 m², giấy chứng nhận chỉ đứng tên ông. Nay ông bán với giá ghi trong hợp đồng 1,8 tỷ đồng; giá đất nhà nước quy định (mô phỏng) 22 triệu đồng/m². Bản nháp hồ sơ HDCN-1207 ghi tình trạng tài sản TS-RIENG và phí công chứng 1480000 đồng. Đối chiếu phiếu kiểm tra đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"This is a training scenario. Mr Hung married in 2015 with no property agreement; in 2019 he bought a 120 m² land plot and the certificate names only him. He now sells it at a contract price of 1.8 billion VND; the state-set land price (training) is 22 million VND/m². Draft file HDCN-1207 records the property status as TS-RIENG (separate) and a notarial fee of 1480000 VND. Compare it with the approved check sheet, correct both fields and write an evidence-based report."},reference_title:{vi:"Phiếu kiểm tra chủ thể, tài sản & phí đã duyệt · HDCN-1207",en:"Approved party, property & fee check sheet · HDCN-1207"},fields:[{id:"ASSET_TYPE",label:{vi:"Tình trạng pháp lý tài sản",en:"Legal status of the property"},initial:"TS-RIENG",expected:"TS-CHUNG-VC",choices:["TS-RIENG","TS-CHUNG-VC","TS-HGD"],reference:"Phiếu kiểm tra chủ thể & tài sản",hint:{vi:"Tài sản có trong thời kỳ hôn nhân, không do thừa kế hay tặng cho riêng, là tài sản chung dù giấy chứng nhận chỉ ghi một người.",en:"Property acquired during marriage, not inherited or gifted separately, is common property even if only one spouse is named."}},{id:"NOTARY_FEE",label:{vi:"Phí công chứng (VND)",en:"Notarial fee (VND)"},initial:"1480000",expected:"1984000",reference:"Bảng tính phí công chứng",ref_value:{vi:"120 m² x 22 triệu đồng/m²; giá hợp đồng 1,8 tỷ đồng; biểu phí mô phỏng ở SOP mục 3.2",en:"120 m² x 22 million VND/m²; contract price 1.8 billion VND; training fee scale in SOP 3.2"},hint:{vi:"Giá ghi trong hợp đồng thấp hơn giá đất nhà nước quy định thì không được lấy làm căn cứ tính phí.",en:"A contract price below the state-set land price cannot be used as the fee base."}}],sop32:{vi:"Giá trị tính phí = giá hợp đồng; nếu thấp hơn diện tích x giá đất nhà nước quy định thì lấy diện tích x giá nhà nước. Biểu mô phỏng cho 1-3 tỷ: phí = 1000000 + 0,06% phần giá trị vượt 1 tỷ đồng.",en:"Fee base = contract price; if it is below area x state-set land price, use area x state price. Training scale for 1-3 billion: fee = 1000000 + 0.06% of the value above 1 billion VND."},context:{label:"HỒ SƠ CÔNG CHỨNG / HDCN-1207",metrics:[{label:{vi:"Diện tích thửa đất",en:"Plot area"},value:"120 m²"},{label:{vi:"Giá ghi trong hợp đồng",en:"Contract price"},value:"1,800,000,000 VND"},{label:{vi:"Giá đất nhà nước (mô phỏng)",en:"State land price (training)"},value:"22,000,000 VND/m²"}]},crisis:{vi:"Người môi giới nói: “Vợ anh Hưng đang ở quê, cứ cho anh ấy ký trước, tối em mang hợp đồng về cho chị ấy ký rồi sáng mai nộp lại. Em gửi anh 5 triệu bồi dưỡng, khách cần công chứng ngay hôm nay.”",en:"The broker says: “Mr Hung's wife is in the countryside, let him sign now and I'll take the contract home for her to sign tonight and bring it back tomorrow. Here's 5 million for your trouble, the client needs it notarised today.”"},options:{safe:{vi:"Từ chối tiền và không cho ký ngoài sự chứng kiến của công chứng viên; báo Trưởng văn phòng, hẹn đủ hai vợ chồng đến ký hoặc làm thủ tục công chứng ngoài trụ sở nếu có lý do chính đáng.",en:"Refuse the money and any signing outside the notary's presence; inform the head notary and book both spouses to sign, or arrange an out-of-office notarisation if there is a valid reason."},shortcut:{vi:"Cho ông Hưng ký trước, nhận lại bản có chữ ký của vợ vào sáng mai để kịp giao dịch.",en:"Let Mr Hung sign now and accept the copy signed by his wife tomorrow morning to close the deal."},wait:{vi:"Không nói gì, để môi giới tự xoay xở rồi tính sau.",en:"Say nothing, let the broker sort it out and decide later."}},questions:{vi:["Vì sao tài sản phải ghi TS-CHUNG-VC dù giấy chứng nhận chỉ đứng tên ông Hưng? Căn cứ pháp lý nào?","Trình bày cách xác định giá trị tính phí công chứng và rủi ro nếu chấp nhận chữ ký không ký trước mặt công chứng viên."],en:["Why must the property be recorded as TS-CHUNG-VC even though only Mr Hung is named? What is the legal basis?","Explain how you set the notarial fee base and the risk of accepting a signature not made before the notary."]},hints:{vi:["Đối chiếu thời điểm kết hôn, thời điểm có tài sản và nguồn gốc tài sản trên phiếu kiểm tra.","So sánh giá hợp đồng với diện tích nhân giá đất nhà nước trước khi áp biểu phí ở SOP mục 3.2.","Đọc lại SOP mục 4.2: các bên phải ký trước mặt công chứng viên, mọi khoản tiền ngoài biểu phí phải từ chối và báo cáo."],en:["Compare the marriage date, acquisition date and origin of the property on the check sheet.","Compare the contract price with area times the state land price before applying the scale in SOP 3.2.","Re-read SOP 4.2: parties must sign before the notary, and any payment outside the fee scale must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên nghiệp vụ công chứng hỗ trợ công chứng viên tiếp nhận yêu cầu, kiểm tra giấy tờ tùy thân, giấy chứng nhận tài sản, năng lực hành vi và tình trạng hôn nhân của các bên, tra cứu thông tin ngăn chặn, soạn dự thảo hợp đồng, tính phí và vào sổ công chứng. Nghề đòi hỏi nắm vững pháp luật dân sự, đất đai, hôn nhân và gia đình, cẩn trọng phát hiện giấy tờ giả và giữ khách quan trước áp lực giao dịch.",en:"A notarial services officer supports the notary by receiving requests, checking identity documents, property certificates, legal capacity and marital status of the parties, searching blocking notices, drafting contracts, calculating fees and entering the notarial register. The role requires solid civil, land and family law knowledge, care in spotting forged papers and impartiality under transaction pressure."},responsibilities:{vi:["Tiếp nhận yêu cầu, kiểm tra giấy tờ tùy thân, giấy chứng nhận và tình trạng hôn nhân của các bên.","Tra cứu thông tin ngăn chặn, thế chấp, tranh chấp của tài sản trên cơ sở dữ liệu công chứng.","Soạn dự thảo hợp đồng, giao dịch đúng ý chí các bên và quy định pháp luật.","Tính phí công chứng, thù lao theo biểu niêm yết và lập biên lai đúng giá trị tính phí.","Vào sổ công chứng, số hóa, lưu trữ hồ sơ và phối hợp cơ quan đăng ký đất đai khi cần."],en:["Receive requests and check the parties' IDs, certificates and marital status.","Search the notarial database for blocking notices, mortgages and disputes on the property.","Draft contracts and transactions that reflect the parties' intent and the law.","Calculate notarial fees and service charges per the posted scale and issue correct receipts.","Enter the notarial register, digitise and archive files and liaise with the land registry when needed."]},competencies:[{name:{vi:"Thẩm định giấy tờ",en:"Document verification"},desc:{vi:"Kiểm tra tính xác thực của căn cước, giấy chứng nhận, giấy xác nhận hôn nhân, phát hiện dấu hiệu giả mạo.",en:"Verify IDs, certificates and marital status papers and spot signs of forgery."}},{name:{vi:"Pháp luật dân sự & đất đai",en:"Civil & land law"},desc:{vi:"Xác định đúng chủ sở hữu, tài sản chung, tài sản riêng, điều kiện chuyển nhượng và người phải ký.",en:"Identify owners, common and separate property, transfer conditions and who must sign."}},{name:{vi:"Soạn thảo hợp đồng",en:"Contract drafting"},desc:{vi:"Soạn điều khoản rõ ràng, đúng mẫu, đúng ý chí các bên, tránh mâu thuẫn và kẽ hở.",en:"Draft clear clauses that fit the template and the parties' intent without conflicts or gaps."}},{name:{vi:"Tính phí & lưu trữ",en:"Fees & archiving"},desc:{vi:"Tính phí trên đúng giá trị, vào sổ, số hóa và lưu trữ hồ sơ theo thời hạn luật định.",en:"Charge fees on the correct base, register, digitise and archive files for the legal period."}},{name:{vi:"Khách quan & liêm chính",en:"Impartiality & integrity"},desc:{vi:"Không nhận tiền ngoài biểu phí, không cho ký hộ, ký ngoài sự chứng kiến của công chứng viên.",en:"Take no money outside the fee scale and allow no proxy signing or signing outside the notary's presence."}}],knowledge:{vi:["Luật Công chứng hiện hành về trình tự công chứng, việc ký trước mặt công chứng viên và các trường hợp công chứng ngoài trụ sở.","Bộ luật Dân sự 2015 về năng lực hành vi, đại diện, hình thức và hiệu lực của giao dịch.","Luật Hôn nhân và gia đình 2014 về tài sản chung, tài sản riêng của vợ chồng và việc định đoạt tài sản chung.","Luật Đất đai 2024 về điều kiện chuyển nhượng quyền sử dụng đất và đăng ký biến động.","Quy định hiện hành về mức thu phí công chứng, kể cả cách xác định giá trị tính phí theo giá đất nhà nước quy định."],en:["Current Law on Notarisation on notarial procedure, signing before the notary and out-of-office notarisation.","Civil Code 2015 on legal capacity, representation, form and validity of transactions.","Law on Marriage and Family 2014 on spouses' common and separate property and disposal of common property.","Land Law 2024 on conditions for transferring land use rights and registering changes.","Current rules on notarial fees, including the fee base set by the state land price."]},tools:["Phần mềm quản lý hồ sơ công chứng","Cơ sở dữ liệu thông tin ngăn chặn","Đèn UV & kính lúp soi giấy tờ","Đầu đọc chip căn cước","Bộ mẫu hợp đồng chuẩn"],kpis:{vi:["Số hồ sơ phát sinh sai sót pháp lý sau công chứng (mục tiêu bằng 0).","Tỷ lệ phí công chứng tính đúng giá trị và đúng biểu ngay lần đầu.","Thời gian xử lý trung bình một hồ sơ hợp đồng chuyển nhượng.","Tỷ lệ hồ sơ được vào sổ, số hóa và lưu trữ đầy đủ trong ngày."],en:["Files with legal defects found after notarisation (target zero).","Share of fees charged on the correct base and scale the first time.","Average processing time for a transfer contract file.","Share of files registered, digitised and archived the same day."]},day:[{time:"08:00",vi:"Tra cứu thông tin ngăn chặn cho các hồ sơ hẹn ký trong ngày.",en:"Search blocking notices for the files booked to sign today."},{time:"09:00",vi:"Tiếp khách, kiểm tra giấy tờ gốc, đọc chip căn cước và tình trạng hôn nhân.",en:"Meet clients, check original papers, read ID chips and verify marital status."},{time:"11:00",vi:"Soạn dự thảo hợp đồng chuyển nhượng và gửi các bên đọc lại.",en:"Draft a transfer contract and send it to the parties to review."},{time:"14:00",vi:"Hỗ trợ công chứng viên tổ chức ký, điểm chỉ trước mặt công chứng viên.",en:"Help the notary run the signing and fingerprinting before the notary."},{time:"16:30",vi:"Tính phí, lập biên lai, vào sổ công chứng và số hóa hồ sơ.",en:"Calculate fees, issue receipts, enter the register and digitise files."}],mistakes:{vi:["Coi giấy chứng nhận chỉ đứng tên một người là tài sản riêng mà không kiểm tra thời điểm và nguồn gốc tài sản.","Tính phí trên giá hợp đồng thấp hơn giá đất nhà nước quy định.","Cho ký hộ hoặc mang hợp đồng ra ngoài cho người khác ký, dẫn tới giao dịch vô hiệu và trách nhiệm bồi thường."],en:["Treating a certificate in one name as separate property without checking when and how it was acquired.","Charging the fee on a contract price below the state-set land price.","Allowing proxy signing or taking the contract out for someone else to sign, voiding the deal and creating liability."]},career:[{vi:"Nhân viên nghiệp vụ công chứng",en:"Notarial assistant"},{vi:"Chuyên viên nghiệp vụ công chứng",en:"Notarial services officer"},{vi:"Công chứng viên (sau đào tạo và tập sự)",en:"Notary public (after training and probation)"},{vi:"Trưởng văn phòng công chứng",en:"Head of notary office"}],glossary:[{term:"Lời chứng",vi:"Phần công chứng viên chứng nhận thời gian, địa điểm, năng lực hành vi, chữ ký và tính hợp pháp của giao dịch.",en:"The notary's attestation of time, place, capacity, signatures and legality of the transaction."},{term:"Thông tin ngăn chặn",vi:"Thông tin cơ quan có thẩm quyền yêu cầu tạm dừng giao dịch đối với một tài sản.",en:"Notice from an authority requiring transactions on a property to be suspended."},{term:"Tài sản chung vợ chồng",vi:"Tài sản vợ chồng tạo ra hoặc có được trong thời kỳ hôn nhân, trừ tài sản được thừa kế, tặng cho riêng.",en:"Property spouses create or acquire during marriage, except separate inheritance or gifts."},{term:"Giá trị tính phí",vi:"Giá trị làm căn cứ tính phí công chứng, không thấp hơn giá trị theo giá nhà nước quy định.",en:"The value used to compute the notarial fee, never below the state-set price value."},{term:"Công chứng ngoài trụ sở",vi:"Việc công chứng thực hiện ngoài văn phòng khi người yêu cầu có lý do chính đáng như già yếu, ốm đau.",en:"Notarisation outside the office when the requester has a valid reason such as old age or illness."}],quiz:[{q:{vi:"Hợp đồng chuyển nhượng 100 m², giá ghi 1,5 tỷ đồng, giá đất nhà nước (mô phỏng) 20 triệu đồng/m². Giá trị tính phí là bao nhiêu?",en:"A 100 m² transfer with a contract price of 1.5 billion VND and a training state price of 20 million VND/m². What is the fee base?"},options:{vi:["1,5 tỷ đồng","3,5 tỷ đồng","2 tỷ đồng","1,75 tỷ đồng"],en:["1.5 billion VND","3.5 billion VND","2 billion VND","1.75 billion VND"]},answer:2,explain:{vi:"100 x 20 triệu = 2 tỷ, cao hơn giá hợp đồng 1,5 tỷ nên giá trị tính phí là 2 tỷ đồng.",en:"100 x 20 million = 2 billion, above the 1.5 billion contract price, so the fee base is 2 billion VND."}},{q:{vi:"Tài sản vợ chồng có trong thời kỳ hôn nhân, không do thừa kế hay tặng cho riêng, được xác định là gì?",en:"Property acquired during marriage, not inherited or gifted separately, is classified as what?"},options:{vi:["Tài sản riêng của người đứng tên","Tài sản chung của vợ chồng","Tài sản của hộ gia đình","Tài sản chưa xác định chủ"],en:["Separate property of the named spouse","Common property of the spouses","Household property","Property with no clear owner"]},answer:1,explain:{vi:"Theo Luật Hôn nhân và gia đình, đó là tài sản chung; việc định đoạt bất động sản chung cần sự đồng ý của cả hai vợ chồng.",en:"Under family law it is common property; disposing of common real estate needs both spouses' consent."}},{q:{vi:"Môi giới đề nghị mang hợp đồng về nhà cho vợ khách ký và gửi tiền bồi dưỡng. Bạn làm gì?",en:"A broker offers money to take the contract home for the client's wife to sign. What do you do?"},options:{vi:["Đồng ý vì khách đã quen","Nhận tiền và yêu cầu chụp ảnh lúc ký","Cho ký nhưng ghi chú vào hồ sơ","Từ chối, báo Trưởng văn phòng và hẹn cả hai vợ chồng ký trước công chứng viên"],en:["Agree since the client is a regular","Take the money and ask for a photo of the signing","Allow it but note it in the file","Refuse, inform the head notary and book both spouses to sign before the notary"]},answer:3,explain:{vi:"Người yêu cầu công chứng phải ký trước mặt công chứng viên; nhận tiền ngoài biểu phí là vi phạm đạo đức hành nghề.",en:"Requesters must sign before the notary; taking money outside the fee scale breaches professional ethics."}},{q:{vi:"Trước khi công chứng hợp đồng chuyển nhượng quyền sử dụng đất, cần tra cứu gì?",en:"What must be searched before notarising a land use right transfer?"},options:{vi:["Thông tin ngăn chặn, thế chấp, tranh chấp của tài sản","Lịch sử tín dụng cá nhân của người mua","Thu nhập hằng tháng của người bán","Giá thị trường trên mạng xã hội"],en:["Blocking notices, mortgages and disputes on the property","The buyer's personal credit history","The seller's monthly income","Market prices on social media"]},answer:0,explain:{vi:"Tài sản bị ngăn chặn, đang thế chấp hoặc tranh chấp có thể không đủ điều kiện giao dịch.",en:"A blocked, mortgaged or disputed property may not be eligible for transfer."}}]}},"KK-982":{scenario:{company:"Viện Chính sách Đô thị An Hòa",supervisor:{name:"Vũ Thanh Hà",role:{vi:"Trưởng nhóm Đánh giá tác động chính sách",en:"Head of Regulatory Impact Assessment"}},ref_code:"RIA-2611",title:{vi:"Tách khoản chuyển giao. Chiết khấu đúng. Báo cáo trung thực.",en:"Net out transfers. Discount correctly. Report honestly."},brief:{vi:"Đây là tình huống đào tạo. Thành phố đề xuất chính sách hỗ trợ đổi xe máy xăng cũ sang xe điện. Năm 0: chi phí triển khai 60 tỷ đồng và tiền trợ giá trả cho hộ dân 240 tỷ đồng. Lợi ích ròng kinh tế (đã trừ chi phí mua xe) 85 tỷ đồng/năm trong năm 1-4. Bản nháp RIA-2611 xếp tiền trợ giá vào COST và báo NPV 40 tỷ đồng. Đối chiếu hướng dẫn phân tích đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"This is a training scenario. The city proposes a policy to help households swap old petrol motorbikes for electric ones. Year 0: implementation cost 60 billion VND and subsidies paid to households 240 billion VND. Economic net benefits (after vehicle purchase costs) are 85 billion VND per year in years 1-4. Draft RIA-2611 books the subsidy as COST and reports an NPV of 40 billion VND. Compare it with the approved guidance, correct both fields and write an evidence-based report."},reference_title:{vi:"Hướng dẫn phân tích chi phí - lợi ích đã duyệt · RIA-2611",en:"Approved cost-benefit analysis guidance · RIA-2611"},fields:[{id:"SUBSIDY_CLS",label:{vi:"Phân loại tiền trợ giá trong CBA",en:"Subsidy classification in the CBA"},initial:"COST",expected:"TRANSFER",choices:["COST","BENEFIT","TRANSFER"],reference:"Hướng dẫn phân loại dòng tiền CBA",hint:{vi:"Ngân sách chi ra đúng bằng số hộ dân nhận được: xã hội không tiêu hao nguồn lực thật nào.",en:"The budget pays out exactly what households receive: society uses up no real resources."}},{id:"NPV_BN",label:{vi:"NPV kinh tế (tỷ đồng)",en:"Economic NPV (billion VND)"},initial:"40",expected:"209",reference:"Bảng chiết khấu dòng lợi ích",ref_value:{vi:"Chi phí kinh tế năm 0 không gồm khoản chuyển giao; lợi ích 85 tỷ/năm, năm 1-4; suất chiết khấu mô phỏng 10%",en:"Year-0 economic cost excludes transfers; benefits 85 billion per year in years 1-4; training discount rate 10%"},hint:{vi:"Bản nháp cộng thẳng lợi ích các năm; lợi ích năm t phải chia cho (1 + r) mũ t.",en:"The draft simply adds yearly benefits; the benefit in year t must be divided by (1 + r) to the power t."}}],sop32:{vi:"NPV = -C0 + Σ Bt/(1+r)^t với t = 1-4; C0 chỉ gồm chi phí nguồn lực thật, loại khoản chuyển giao (trợ giá, thuế); r = 10% (mô phỏng); làm tròn đến số nguyên tỷ đồng.",en:"NPV = -C0 + Σ Bt/(1+r)^t for t = 1-4; C0 covers only real resource costs and excludes transfers (subsidies, taxes); r = 10% (training); round to the nearest billion VND."},context:{label:"RIA / RIA-2611",metrics:[{label:{vi:"Chi phí triển khai năm 0",en:"Year-0 implementation cost"},value:"60,000,000,000 VND"},{label:{vi:"Trợ giá cho hộ dân",en:"Household subsidy"},value:"240,000,000,000 VND"},{label:{vi:"Lợi ích ròng mỗi năm",en:"Net benefit per year"},value:"85,000,000,000 VND x 4"},{label:{vi:"Suất chiết khấu mô phỏng",en:"Training discount rate"},value:"10%"}]},crisis:{vi:"Phó viện trưởng nhắn: “Lãnh đạo thành phố đã công bố chương trình rồi. Em bỏ kịch bản giá xăng giảm làm NPV âm và gom bớt ý kiến phản đối trong tham vấn đi, báo cáo nộp sáng mai chỉ nên có số đẹp.”",en:"The deputy director texts: “City leaders have already announced the programme. Drop the low fuel price scenario that turns NPV negative and trim the opposing consultation comments, tomorrow's report should only show good numbers.”"},options:{safe:{vi:"Giữ đầy đủ phân tích độ nhạy và ý kiến tham vấn, trình bày rủi ro minh bạch, báo Viện trưởng và đề xuất phương án giảm rủi ro như thí điểm theo giai đoạn.",en:"Keep the full sensitivity analysis and consultation comments, present risks transparently, inform the director and propose risk-reducing options such as a phased pilot."},shortcut:{vi:"Xóa kịch bản bất lợi và ý kiến phản đối để báo cáo đẹp, đúng ý lãnh đạo.",en:"Delete the adverse scenario and opposing comments so the report pleases leadership."},wait:{vi:"Nộp bản nháp như cũ và để Phó viện trưởng tự sửa.",en:"Submit the draft unchanged and let the deputy director edit it."}},questions:{vi:["Vì sao tiền trợ giá là TRANSFER chứ không phải COST trong phân tích kinh tế? Điều đó thay đổi NPV ra sao?","Trình bày cách chiết khấu dòng lợi ích và vì sao phải giữ kịch bản độ nhạy bất lợi trong báo cáo."],en:["Why is the subsidy a TRANSFER rather than a COST in the economic analysis? How does that change the NPV?","Explain how you discounted the benefit stream and why the adverse sensitivity scenario must stay in the report."]},hints:{vi:["Đặt bản nháp cạnh hướng dẫn phân loại dòng tiền và đánh dấu khoản bị xếp sai.","Loại khoản chuyển giao khỏi chi phí năm 0 rồi chiết khấu từng năm theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được loại bỏ dữ liệu bất lợi hay ý kiến tham vấn để làm đẹp kết quả."],en:["Place the draft next to the cash flow classification guidance and flag the misclassified item.","Remove transfers from the year-0 cost, then discount each year per SOP 3.2.","Re-read SOP 4.2: adverse data and consultation comments must never be removed to polish the results."]}},learning:{summary:{vi:"Chuyên viên phân tích chính sách công xác định vấn đề chính sách, xây dựng các phương án, đánh giá tác động kinh tế, xã hội, môi trường, giới và thủ tục hành chính, rồi khuyến nghị phương án phù hợp cho cơ quan ra quyết định. Nghề đòi hỏi phương pháp định lượng như CBA, CEA, hiểu quy trình xây dựng chính sách, kỹ năng tham vấn và viết báo cáo khách quan, minh bạch về giả định và giới hạn.",en:"A public policy analyst defines policy problems, designs options, assesses economic, social, environmental, gender and administrative impacts and recommends a suitable option to decision makers. The role requires quantitative methods such as CBA and CEA, knowledge of the policy-making process, consultation skills and objective reporting that is transparent about assumptions and limits."},responsibilities:{vi:["Xác định vấn đề, mục tiêu chính sách và các nhóm chịu tác động.","Thiết kế các phương án chính sách, kể cả phương án giữ nguyên hiện trạng làm mốc so sánh.","Thu thập dữ liệu, ước lượng chi phí, lợi ích và phân tích độ nhạy.","Tổ chức tham vấn các bên liên quan và tổng hợp ý kiến trung thực, đầy đủ.","Viết báo cáo đánh giá tác động, khuyến nghị và đề xuất khung giám sát sau ban hành."],en:["Define the problem, policy objectives and affected groups.","Design policy options, including a do-nothing baseline for comparison.","Collect data, estimate costs and benefits and run sensitivity analysis.","Run stakeholder consultations and summarise views truthfully and completely.","Write the impact assessment report with recommendations and a post-adoption monitoring framework."]},competencies:[{name:{vi:"Phân tích chi phí - lợi ích",en:"Cost-benefit analysis"},desc:{vi:"Phân biệt chi phí nguồn lực với khoản chuyển giao, chiết khấu dòng tiền và tính NPV, B/C.",en:"Separate resource costs from transfers, discount cash flows and compute NPV and B/C ratios."}},{name:{vi:"Thiết kế phương án chính sách",en:"Policy option design"},desc:{vi:"Xây dựng các lựa chọn khả thi về công cụ quy định, tài chính, thông tin và so sánh với mốc cơ sở.",en:"Build feasible regulatory, fiscal and information options and compare them with the baseline."}},{name:{vi:"Phân tích dữ liệu & độ nhạy",en:"Data & sensitivity analysis"},desc:{vi:"Kiểm định độ vững của kết quả theo kịch bản, giá trị ngưỡng và độ bất định của giả định.",en:"Test result robustness with scenarios, switching values and assumption uncertainty."}},{name:{vi:"Tham vấn & truyền thông chính sách",en:"Consultation & communication"},desc:{vi:"Lắng nghe các nhóm chịu tác động và trình bày kết quả dễ hiểu cho người ra quyết định.",en:"Listen to affected groups and present findings clearly to decision makers."}},{name:{vi:"Khách quan khoa học",en:"Scientific objectivity"},desc:{vi:"Báo cáo cả kết quả bất lợi, công khai giả định và không điều chỉnh số liệu theo ý muốn.",en:"Report adverse results, disclose assumptions and never bend numbers to a preferred answer."}}],knowledge:{vi:["Quy trình xây dựng chính sách và đánh giá tác động chính sách theo pháp luật hiện hành về ban hành văn bản quy phạm pháp luật.","Nguyên tắc phân tích chi phí - lợi ích kinh tế: chi phí cơ hội, khoản chuyển giao, giá mờ, suất chiết khấu xã hội.","Phân tích chi phí - hiệu quả (CEA) và phân tích đa tiêu chí (MCA) khi lợi ích khó lượng hóa bằng tiền.","Khung đánh giá tác động pháp quy (RIA) và hướng dẫn thực hành tốt của OECD.","Khung theo dõi, đánh giá (M&E) và chuỗi kết quả đầu vào - đầu ra - kết quả - tác động."],en:["Policy-making and policy impact assessment under the current law on promulgating legal documents.","Economic CBA principles: opportunity cost, transfers, shadow prices and the social discount rate.","Cost-effectiveness analysis (CEA) and multi-criteria analysis (MCA) when benefits are hard to monetise.","The regulatory impact assessment (RIA) framework and OECD good practice guidance.","Monitoring and evaluation (M&E) frameworks and the input - output - outcome - impact results chain."]},tools:["Bảng tính mô hình CBA","Ngôn ngữ R hoặc Python","Phần mềm thống kê","Công cụ khảo sát trực tuyến","Bản đồ GIS"],kpis:{vi:["Tỷ lệ báo cáo được hội đồng thẩm định chấp nhận mà không phải làm lại phần phân tích.","Mức độ đầy đủ của giả định, nguồn dữ liệu và phân tích độ nhạy trong báo cáo.","Thời gian hoàn thành đánh giá tác động so với kế hoạch xây dựng văn bản.","Tỷ lệ khuyến nghị được tiếp thu và có chỉ số giám sát sau ban hành."],en:["Share of reports accepted by the appraisal council without reworking the analysis.","Completeness of assumptions, data sources and sensitivity analysis in reports.","Time to complete the impact assessment versus the drafting plan.","Share of recommendations adopted with post-adoption monitoring indicators."]},day:[{time:"08:30",vi:"Rà soát dữ liệu mới từ cơ quan thống kê và khảo sát hộ gia đình.",en:"Review new data from the statistics office and household surveys."},{time:"10:00",vi:"Cập nhật mô hình CBA, kiểm tra phân loại dòng tiền và chiết khấu.",en:"Update the CBA model and check cash flow classification and discounting."},{time:"13:30",vi:"Chủ trì phiên tham vấn với hiệp hội, người dân và doanh nghiệp.",en:"Chair a consultation with associations, residents and businesses."},{time:"15:30",vi:"Chạy phân tích độ nhạy theo giá nhiên liệu và tỷ lệ hộ tham gia.",en:"Run sensitivity analysis on fuel prices and household take-up."},{time:"17:00",vi:"Viết phần khuyến nghị, ghi rõ giả định và giới hạn của phân tích.",en:"Write the recommendations, stating assumptions and limits of the analysis."}],mistakes:{vi:["Tính khoản chuyển giao như trợ giá, thuế vào chi phí kinh tế, làm sai lệch NPV.","Cộng thẳng lợi ích nhiều năm mà không chiết khấu về giá trị hiện tại.","Lược bỏ kịch bản bất lợi hoặc ý kiến phản biện để báo cáo ủng hộ quyết định đã định sẵn."],en:["Counting transfers such as subsidies and taxes as economic costs, distorting the NPV.","Adding multi-year benefits without discounting them to present value.","Removing adverse scenarios or critical comments so the report backs a decision already made."]},career:[{vi:"Trợ lý nghiên cứu chính sách",en:"Policy research assistant"},{vi:"Chuyên viên phân tích chính sách",en:"Policy analyst"},{vi:"Chuyên viên chính, trưởng nhóm đánh giá tác động",en:"Senior analyst, impact assessment lead"},{vi:"Chuyên gia cao cấp, giám đốc nghiên cứu chính sách",en:"Principal expert, director of policy research"}],glossary:[{term:"CBA",vi:"Phân tích chi phí - lợi ích: so sánh toàn bộ chi phí và lợi ích xã hội quy ra tiền của một phương án.",en:"Cost-benefit analysis: comparing all monetised social costs and benefits of an option."},{term:"NPV",vi:"Giá trị hiện tại ròng: tổng lợi ích trừ chi phí sau khi chiết khấu về thời điểm hiện tại.",en:"Net present value: benefits minus costs after discounting to the present."},{term:"Transfer payment",vi:"Khoản chuyển giao như thuế, trợ cấp, chỉ chuyển tiền giữa các nhóm, không tiêu hao nguồn lực thật.",en:"A payment such as a tax or subsidy that moves money between groups without using real resources."},{term:"Sensitivity analysis",vi:"Phân tích kết quả thay đổi thế nào khi giả định quan trọng thay đổi.",en:"Analysis of how results change when key assumptions change."},{term:"RIA",vi:"Đánh giá tác động pháp quy: quy trình phân tích hệ quả của chính sách trước khi ban hành.",en:"Regulatory impact assessment: analysing a policy's consequences before adoption."}],quiz:[{q:{vi:"Lợi ích 110 tỷ đồng nhận sau đúng 1 năm, suất chiết khấu 10%. Giá trị hiện tại là bao nhiêu?",en:"A benefit of 110 billion VND arrives in exactly 1 year at a 10% discount rate. What is its present value?"},options:{vi:["121 tỷ đồng","110 tỷ đồng","99 tỷ đồng","100 tỷ đồng"],en:["121 billion VND","110 billion VND","99 billion VND","100 billion VND"]},answer:3,explain:{vi:"PV = 110 ÷ 1,1 = 100 tỷ đồng.",en:"PV = 110 ÷ 1.1 = 100 billion VND."}},{q:{vi:"Trong CBA kinh tế, thuế và trợ giá giữa Nhà nước và người dân được xử lý thế nào?",en:"In an economic CBA, how are taxes and subsidies between the state and citizens treated?"},options:{vi:["Là khoản chuyển giao, không tính vào chi phí nguồn lực","Luôn tính là chi phí","Luôn tính là lợi ích","Tính gấp đôi để thận trọng"],en:["As transfers, excluded from resource costs","Always as costs","Always as benefits","Counted twice for prudence"]},answer:0,explain:{vi:"Khoản chuyển giao chỉ phân phối lại tiền giữa các nhóm; tính vào chi phí sẽ làm sai lệch kết quả.",en:"Transfers only redistribute money between groups; counting them as costs distorts the result."}},{q:{vi:"Lãnh đạo yêu cầu bỏ kịch bản làm NPV âm trước khi nộp báo cáo. Bạn làm gì?",en:"A leader asks you to drop the scenario that makes NPV negative before submission. What do you do?"},options:{vi:["Xóa kịch bản cho nhanh","Giữ kịch bản, trình bày minh bạch và báo cáo cấp có thẩm quyền","Sửa giả định để NPV dương","Không nộp báo cáo"],en:["Delete it to save time","Keep it, present it transparently and inform the proper authority","Tweak assumptions until NPV is positive","Do not submit the report"]},answer:1,explain:{vi:"Người ra quyết định cần thấy đầy đủ rủi ro; che giấu kết quả bất lợi vi phạm chuẩn mực nghề nghiệp.",en:"Decision makers need the full risk picture; hiding adverse results breaches professional standards."}},{q:{vi:"Khi lợi ích chính là số ca bệnh tránh được và khó quy ra tiền, nên dùng phương pháp nào?",en:"When the main benefit is cases of illness avoided and hard to monetise, which method fits?"},options:{vi:["Phân tích hòa vốn","Phân tích dòng tiền tài chính","Phân tích chi phí - hiệu quả (CEA)","Định giá cổ phiếu"],en:["Break-even analysis","Financial cash flow analysis","Cost-effectiveness analysis (CEA)","Equity valuation"]},answer:2,explain:{vi:"CEA so sánh chi phí trên mỗi đơn vị kết quả như chi phí cho mỗi ca bệnh tránh được.",en:"CEA compares cost per unit of outcome, such as cost per case of illness avoided."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(15)})(window.KKR);
